-- Generated by tools/bundle.lua from src/. Do not edit.
local uz = uz or fb  -- Uzume < 0.22 only has the old name fb
local __mod = {}
local __loaded = {}
local function require(name)
  local m = __loaded[name]
  if m ~= nil then
    if m == __loaded then return nil end
    return m
  end
  local f = __mod[name]
  if not f then return nil end
  __loaded[name] = __loaded -- cycle guard
  local r = f(name)
  if r == nil then r = true end
  __loaded[name] = r
  return r
end
__mod["core.adapters"] = function(...)
-- Static adapter registry. A module that is missing is skipped.
local M = {}

local function try(name)
  local ok, mod = pcall(require, name)
  if ok and type(mod) == "table" then return mod end
  return nil
end

M.REGISTRY = {}
for _, name in ipairs({ "gen6.oras", "demo.adapter" }) do
  M.REGISTRY[name] = try(name)
end

function M.get(name)
  if not name then return nil end
  return M.REGISTRY[name]
end

return M

end
