-- Region letter (4th char of an NDS/GBA game code) -> language
local LANG = { D = "de", F = "fr", I = "it", S = "es", E = "en", P = "en", J = "ja", K = "ko" }

-- Returns entry, info for an uz.game-like table; nil for unknown games.
function M.detect(game)
  if type(game) ~= "table" or type(game.system) ~= "string" or type(game.code) ~= "string" then
    return nil
  end
  local system = game.system:lower()
  local code = game.code:upper()
  if system == "3ds" then
    code = code:gsub("^0X", "")
    for _, e in ipairs(M.GAMES) do
      if e.system == "3ds" then
        for _, c in ipairs(e.codes) do
          if c == code then return e, { region_letter = nil, language = nil } end
        end
      end
    end
    return nil
  end
  if #code < 4 then return nil end
  local prefix, letter = code:sub(1, 3), code:sub(4, 4)
  for _, e in ipairs(M.GAMES) do
    if e.system == system then
      for _, c in ipairs(e.codes) do
        if c == prefix then
          return e, { region_letter = letter, language = LANG[letter] }
        end
      end
    end
  end
  return nil
end

return M

end
__mod["core.interface"] = function(...)
-- Builds the table for uz.provide("pokemon.core", tbl).
local M = {}

local METHODS = { "team", "box", "box_count", "location", "battle", "encounters", "badges", "balls", "bag", "abilities", "trainer", "name",
  "species_info", "areas", "locations", "zone_info", "icon", "icon_variants", "map_candidates", "map_image", "map_selected", "diagnostics",
  "encode_pokemon", "encode_money", "encode_item", "edit_limits", "names_list" }
local FEATURE = {
  team = "team", box = "box", location = "location",
  battle = "battle", encounters = "encounters", badges = "badges", balls = "balls", bag = "bag", abilities = "abilities", trainer = "trainer", name = "names",
  areas = "areas", locations = "locations", icon = "icons", map_candidates = "map", diagnostics = "diagnostics",
  encode_pokemon = "edit_pokemon", encode_money = "edit_money", encode_item = "edit_items", names_list = "name_lists",
}

local function has(adapter, name)
  return adapter ~= nil and type(adapter[name]) == "function"
end

-- entry: games.lua entry, detected: info from games.detect, adapter: adapter object or nil
function M.new(entry, detected, adapter)
  local api = {}

  function api.info()
    local features = { live_stats = false }
    for method, key in pairs(FEATURE) do features[key] = has(adapter, method) end
    -- An adapter may refine features that depend on runtime state (icons found, address set).
    if has(adapter, "features") then
      local over = adapter:features()
      if type(over) == "table" then
        for k, v in pairs(over) do features[k] = v == true end
      end
    end
    local language = detected and detected.language or nil
    if has(adapter, "language") then language = adapter:language() or language end
    local revision
    if has(adapter, "revision") then revision = adapter:revision() end
    local icon_rev
    if has(adapter, "icon_rev") then icon_rev = adapter:icon_rev() end
    local demo = has(adapter, "demo") and adapter:demo() == true
    return {
      demo = demo,
      icon_rev = icon_rev,
      game_id = entry.id,
      name = entry.name,
      gen = entry.gen,
      system = entry.system,
      version = entry.version,
      language = language,
      revision = revision,
      supported = adapter ~= nil,
      features = features,
    }
  end

  for _, method in ipairs(METHODS) do
    api[method] = function(...)
      if not has(adapter, method) then return nil, "unsupported" end
      return adapter[method](adapter, ...)
    end
  end

  return api
end

return M

end
__mod["core.serialize"] = function(...)
-- Deterministic serialization (sorted keys), used to compare values for changes.
local M = {}

local function ser(v, out)
  local t = type(v)
  if t == "table" then
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b)
      local ta, tb = type(a), type(b)
      if ta ~= tb then return ta < tb end
      return a < b
    end)
    out[#out + 1] = "{"
    for _, k in ipairs(keys) do
      out[#out + 1] = type(k) == "string" and string.format("%q", k) or tostring(k)
      out[#out + 1] = "="
      ser(v[k], out)
      out[#out + 1] = ","
    end
    out[#out + 1] = "}"
  elseif t == "string" then
    out[#out + 1] = string.format("%q", v)
  else
    out[#out + 1] = tostring(v)
  end
end

function M.serialize(v)
  local out = {}
  ser(v, out)
  return table.concat(out)
end

return M

end
__mod["demo.adapter"] = function(...)
-- Demo adapter: serves synthetic data through the same adapter contract as the ORAS adapter, on a scripted
-- timeline driven by ticks. Runs only when the developer setting "Demo data" is on (see main.lua), never
-- automatically. No game memory is read.
local data = require("demo.data")

local M = {}

local function copy(t)
  local c = {}
  for k, v in pairs(t) do c[k] = type(v) == "table" and copy(v) or v end
  return c
end

local function find_location(zone)
  for _, l in ipairs(data.LOCATIONS) do
    for _, z in ipairs(l.zones) do
      if z == zone then return l end
    end
  end
  return nil
end

-- Synthetic square icon: a colour derived from the species id, a darker frame. nil when no PNG encoder exists.
local function make_icon(uz, species)
  if type(uz.codec) ~= "table" or type(uz.codec.png) ~= "function" then return nil end
  local w, h = 32, 32
  local r, g, b = (species * 53) % 200 + 40, (species * 97) % 200 + 40, (species * 29) % 200 + 40
  local px = {}
  for y = 0, h - 1 do
    for x = 0, w - 1 do
      local edge = x < 2 or y < 2 or x >= w - 2 or y >= h - 2
      if edge then
        px[#px + 1] = string.char(r // 3, g // 3, b // 3, 255)
      else
        px[#px + 1] = string.char(r, g, b, 255)
      end
    end
  end
  local ok, png = pcall(uz.codec.png, { width = w, height = h, rgba = table.concat(px) })
  if ok and type(png) == "string" then return png end
  return nil
end

function M.attach(ctx)
  local uz = ctx.uz
  local timeline = ctx.timeline or data.TIMELINE
  local obj = {}

  -- The host calls the tick function only while a memory snapshot exists, and a snapshot exists only while some range
  -- is registered. The demo reads no memory, so it registers one byte (no data is used) to keep its timeline running.
  if type(uz.memory) == "table" and type(uz.memory.watch) == "function" then pcall(uz.memory.watch, "demo.clock", 0, 1) end

  local ticks = 0
  local next_step = 1
  local team = data.start_team()
  local box = data.start_box()
  local zone = 101
  local badges = 0
  local battle = { active = false }
  local encounters = {}
  local seq = 0
  local icons = {}

  local function loc_table()
    local l = find_location(zone)
    return { zone = zone, location = l and l.id or nil, name = l and l.name or nil, source = "memory",
      x = 10.0, y = 20.0 }
  end

  local function with_names(rec)
    local r = copy(rec)
    r.species_name = data.name("species", r.species)
    return r
  end

  local function emit_location()
    uz.events.emit("location.changed", loc_table())
  end

  local function start_battle(kind, species, level)
    local foe = { species = species, form = 0, level = level, hp = level * 4, max_hp = level * 4, shiny = false,
      personality = 0x1A2B0100 + seq + 1 }
    battle = { active = true, kind = kind, horde = false, foes = { foe }, own = {} }
    for i, m in ipairs(team) do
      battle.own[#battle.own + 1] = { personality = m.personality, species = m.species, hp = m.hp,
        max_hp = m.max_hp, slot = i }
    end
    uz.events.emit("battle.started", { kind = kind, horde = false, foes = { species } })
    if kind == "wild" then
      seq = seq + 1
      local l = find_location(zone)
      local e = { seq = seq, species = species, form = 0, level = level, shiny = false, horde = false,
        zone = zone, location = l and l.id or nil, frame = ticks }
      encounters[#encounters + 1] = e
      uz.events.emit("encounter", with_names(e))
    end
  end

  local function end_battle()
    local kind = battle.kind
    battle = { active = false }
    if kind then uz.events.emit("battle.ended", { kind = kind }) end
  end

  local handlers = {}
  function handlers.move(s) zone = s.zone; emit_location() end
  function handlers.wild_start(s) start_battle("wild", s.species, s.level) end
  function handlers.trainer_start(s) start_battle("trainer", s.species, s.level) end
  function handlers.catch()
    if #team < 6 then
      local m = data.catch_mon()
      m.slot = #team + 1
      team[#team + 1] = m
    end
    end_battle()
  end
  function handlers.faint(s)
    local m = team[s.slot]
    if m then m.hp = 0 end
  end
  function handlers.battle_end() end_battle() end
  function handlers.badge(s)
    local old = badges
    badges = math.max(badges, s.index)
    if badges ~= old then
      local new = {}
      for i = old + 1, badges do new[#new + 1] = i end
      uz.events.emit("badges.changed", { count = badges, new = new })
    end
  end

  function obj:demo() return true end
  function obj:revision() return "demo" end
  function obj:language() return "en" end
  function obj:icon_rev() return "demo-1" end

  -- Advances the scripted timeline by one tick; due steps run in order.
  function obj:tick()
    ticks = ticks + 1
    while next_step <= #timeline and timeline[next_step].at <= ticks do
      local s = timeline[next_step]
      next_step = next_step + 1
      local h = handlers[s.step]
      if h then h(s) end
    end
  end

  function obj:ticks() return ticks end

  function obj:features()
    return { icons = type(uz.codec) == "table" and type(uz.codec.png) == "function", names = true, areas = true,
      locations = true, live_stats = true, location = true, battle = true, encounters = true }
  end

  function obj:team()
    local out = {}
    for i, m in ipairs(team) do
      local r = with_names(m)
      r.slot = i
      out[#out + 1] = r
    end
    return out
  end

  function obj:box_count() return 31 end

  function obj:box(n)
    if math.type(n) ~= "integer" or n < 1 or n > 31 then return nil, "invalid_box" end
    local out = {}
    if n == 1 then
      for i, m in ipairs(box) do
        local r = with_names(m)
        r.box, r.slot = 1, i
        out[#out + 1] = r
      end
    end
    return out
  end

  function obj:location() return loc_table() end

  function obj:battle()
    if not battle.active then return { active = false } end
    local b = copy(battle)
    for _, f in ipairs(b.foes) do f.species_name = data.name("species", f.species) end
    b.own = {}
    for i, m in ipairs(team) do
      b.own[#b.own + 1] = { personality = m.personality, species = m.species, hp = m.hp, max_hp = m.max_hp,
        slot = i, species_name = data.name("species", m.species) }
    end
    return b
  end

  function obj:encounters()
    local out = {}
    for _, e in ipairs(encounters) do out[#out + 1] = with_names(e) end
    return out
  end

  function obj:badges()
    local flags = {}
    for i = 1, 8 do flags[i] = i <= badges end
    return { count = badges, flags = flags }
  end

  function obj:trainer()
    return { name = "DEMO", tid = 4242, sid = 2424, version = "demo", language = "en", money = 3000,
      badges = badges, play_time = { h = 0, m = ticks // (60 * data.TICKS_PER_SECOND) % 60,
        s = ticks // data.TICKS_PER_SECOND % 60 } }
  end

  function obj:name(kind, id) return data.name(kind, id) end

  function obj:species_info(species, form)
    if math.type(species) ~= "integer" or species < 1 then return nil, "unknown_species" end
    if form and form ~= 0 then return nil, "no_form" end
    local t1 = species % 4 + 1
    return { types = { t1, t1 }, growth = 0 }
  end

  function obj:areas()
    local out = {}
    for _, l in ipairs(data.LOCATIONS) do
      if l.encounters then
        out[#out + 1] = { id = l.id, name = l.name, zones = copy(l.zones), encounters = copy(l.encounters) }
      end
    end
    return out
  end

  function obj:locations()
    local out = {}
    for _, l in ipairs(data.LOCATIONS) do
      out[#out + 1] = { id = l.id, name = l.name, zones = copy(l.zones), has_encounters = l.encounters ~= nil,
        source = "zones" }
    end
    return out
  end

  function obj:zone_info(z)
    local l = find_location(z)
    if not l then return nil, "unknown_zone" end
    return { zone = z, location = l.id, name = l.name }
  end

  function obj:icon(species, form)
    if math.type(species) ~= "integer" or species < 1 then return nil, "unknown_species" end
    local key = species
    if icons[key] == nil then icons[key] = make_icon(uz, species) or false end
    if not icons[key] then return nil, "unsupported" end
    return icons[key]
  end

  function obj:diagnostics()
    return { demo = 1, ticks = ticks, step = next_step - 1, zone = zone, team = #team, badges = badges }
  end

  return obj
end

return M

end
__mod["demo.data"] = function(...)
-- Synthetic demo data for the demo adapter. Everything here is invented: no real species, location or
-- move names, and no ids are looked up in a game. Names are marked "Demo" so they can never be mistaken
-- for game text.
local M = {}

M.TICKS_PER_SECOND = 30

-- Name kinds that the interface knows (`name(kind, id)`).
M.KINDS = { species = "Demomon", move = "Demo Move", item = "Demo Item", ability = "Demo Ability",
  nature = "Demo Nature", type = "Demo Type", form = "Demo Form" }

-- Locations: id -> name, zone -> location. Two routes have encounter areas.
M.LOCATIONS = {
  { id = 1001, name = "Demo Town", zones = { 101 }, encounters = nil },
  { id = 1002, name = "Demo Route 1", zones = { 102 },
    encounters = { grass = { { species = 21, form = 0, min = 2, max = 4 }, { species = 22, form = 0, min = 2, max = 4 } } } },
  { id = 1003, name = "Demo Route 2", zones = { 103 },
    encounters = { grass = { { species = 23, form = 0, min = 4, max = 6 }, { species = 24, form = 0, min = 4, max = 6 } } } },
}

local function mon(personality, species, nick, level, hp, moves)
  return {
    species = species, form = 0, nickname = nick, level = level, exp = level * level * level,
    personality = personality, shiny = false, gender = personality % 2, nature = personality % 25,
    ability = 1 + personality % 3, held_item = 0, moves = moves, ot_name = "DEMO", ot_id = 4242, ot_sid = 2424,
    language = "en", egg = false, hp = hp, max_hp = hp, status = 0,
  }
end
M.mon = mon

-- Starting team (3 creatures) and one box creature.
function M.start_team()
  return {
    mon(0x1A2B0001, 11, "Sprout", 5, 22, { 1, 2 }),
    mon(0x1A2B0002, 12, "Ember", 5, 20, { 1, 3 }),
    mon(0x1A2B0003, 13, "Drip", 5, 24, { 1, 4 }),
  }
end

function M.start_box()
  return { mon(0x1A2B0010, 14, "Boxer", 4, 18, { 1 }) }
end

-- The creature that is caught in the scripted timeline.
function M.catch_mon()
  return mon(0x1A2B0021, 21, nil, 3, 14, { 1 })
end

-- Scripted timeline: tick counts at 30 ticks per second; `do_` names the step handled by the adapter.
local S = M.TICKS_PER_SECOND
M.TIMELINE = {
  { at = 10 * S, step = "move", zone = 102 },       -- Demo Town -> Demo Route 1
  { at = 15 * S, step = "wild_start", species = 21, level = 3 },
  { at = 20 * S, step = "catch" },                  -- the wild creature joins the team, battle ends
  { at = 30 * S, step = "move", zone = 103 },       -- -> Demo Route 2
  { at = 40 * S, step = "trainer_start", species = 23, level = 6 },
  { at = 45 * S, step = "faint", slot = 4 },        -- team member 4 (the caught creature) faints
  { at = 50 * S, step = "battle_end" },
  { at = 60 * S, step = "badge", index = 1 },       -- first badge
}

function M.name(kind, id)
  if math.type(id) ~= "integer" then return nil end
  if kind == "location" then
    for _, l in ipairs(M.LOCATIONS) do
      if l.id == id then return l.name end
    end
    return nil
  end
  local base = M.KINDS[kind]
  if not base then return nil end
  return base .. " " .. id
end

return M

end
__mod["gen6.darc"] = function(...)
-- Parser for DARC archives (3DS UI archives), read-only, bounds-checked.
-- Format (3dbrew "DARC"): header "darc", u16 BOM, u16 header size (0x1C), u32 version,
-- u32 file size, u32 file table offset, u32 file table length, u32 data offset.
-- File table: 12-byte entries {u32 flags<<24 | name offset, u32 a, u32 b}; flag 1 =
-- directory (a = parent index, b = index after its last descendant), else file
-- (a = data offset from file start, b = length). Entry 0 is the root and its b is
-- the entry count. Names (UTF-16LE, zero terminated) start behind the entry table.
local M = {}

M.MAX_ENTRIES = 4096

local function name_at(s, base, off)
  local pos, chars = base + off + 1, {}
  while #chars < 128 do
    if pos + 1 > #s then return nil end
    local c = string.unpack("<I2", s, pos)
    if c == 0 then break end
    chars[#chars + 1] = c < 128 and string.char(c) or "?"
    pos = pos + 2
  end
  return table.concat(chars)
end

-- Returns an array of { path, offset, length } (offset 0-based) or nil, message.
function M.parse(s)
  if type(s) ~= "string" or #s < 0x1C or s:sub(1, 4) ~= "darc" then return nil, "not a darc" end
  local tbl_off, tbl_len = string.unpack("<I4I4", s, 0x11)
  if tbl_off < 0x1C or tbl_off + 12 > #s or tbl_off + tbl_len > #s then return nil, "bad table" end
  local count = string.unpack("<I4", s, tbl_off + 8 + 1)
  if count < 1 or count > M.MAX_ENTRIES or tbl_off + count * 12 > #s then return nil, "bad count" end
  local names = tbl_off + count * 12
  local out, stack = {}, {}
  for i = 1, count - 1 do
    local nf, a, b = string.unpack("<I4I4I4", s, tbl_off + i * 12 + 1)
    while #stack > 0 and i >= stack[#stack].last do stack[#stack] = nil end
