    if (nf >> 24) == 1 then
      if b <= i or b > count or #stack >= 16 then return nil, "bad directory" end
      stack[#stack + 1] = { name = name, last = b }
    else
      if a + b > #s then return nil, "bad file" end
      local parts = {}
      for _, d in ipairs(stack) do parts[#parts + 1] = d.name end
      parts[#parts + 1] = name
      out[#out + 1] = { path = table.concat(parts, "/"), offset = a, length = b }
    end
  end
  return out
end

return M

end
__mod["gen6.garc_entry"] = function(...)
-- Shared GARC entry reading. pk3DS reads every GARC entry through GARCEntry, which LZ11-decompresses
-- any entry whose first byte is 0x11 and keeps the raw bytes when that fails (pk3DS.Core/CTR/GARC.cs).
-- Plain readers (text, personal, icons) use `entry`; zones and maps use `decompress` directly.
local M = {}

M.MAX_LZ_OUTPUT = 8 * 1024 * 1024 -- output size limit of a decompressed entry

-- Decompresses `e` when its first byte is 0x11 (also 0x10 with allow_lz10) via codec.lz_decompress.
-- Returns data, status: "lz" (decompressed), "raw" (not compressed or no codec) or
-- "lz_failed" (data = the raw entry; decompression raised, returned a non-string or exceeded the limit).
function M.decompress(codec, e, allow_lz10)
  if type(e) ~= "string" then return e, "raw" end
  local b = e:byte(1)
  if (b == 0x11 or (allow_lz10 and b == 0x10)) and codec and codec.lz_decompress then
    local ok, out = pcall(codec.lz_decompress, e)
    if ok and type(out) == "string" and #out <= M.MAX_LZ_OUTPUT then return out, "lz" end
    return e, "lz_failed"
  end
  return e, "raw"
end

-- GARC file `index` (1-based, first sub-file), decompressed if needed. Returns data, status
-- (see decompress); nil, "garc_error" | "no_entry" when the entry cannot be read.
function M.entry(codec, d, index)
  local ok, e = pcall(codec.garc_file, d, index, 1)
  if not ok then return nil, "garc_error" end
  if type(e) ~= "string" or #e == 0 then return nil, "no_entry" end
  return M.decompress(codec, e)
end

return M

end
__mod["gen6.growth"] = function(...)
-- EXP <-> level for the six standard growth curves (formulas only, no tables).
-- Rate IDs follow the games' personal data (PKHeX: Experience.GetEXPTable /
-- PersonalInfo.EXPGrowth): 0 medium fast, 1 erratic, 2 fluctuating,
-- 3 medium slow, 4 fast, 5 slow.
-- Formulas: Bulbapedia "Experience" (integer division rounds down).
local M = {}

M.MEDIUM_FAST, M.ERRATIC, M.FLUCTUATING = 0, 1, 2
M.MEDIUM_SLOW, M.FAST, M.SLOW = 3, 4, 5
M.MAX_LEVEL = 100

-- Total EXP needed to reach level n (1..100) with the given rate; nil for bad input.
function M.exp_for_level(rate, n)
  if math.type(n) ~= "integer" or n < 1 or n > 100 then return nil end
  if n == 1 then return 0 end
  local c = n * n * n
  if rate == 0 then
    return c
  elseif rate == 1 then
    if n < 50 then return c * (100 - n) // 50 end
    if n < 68 then return c * (150 - n) // 100 end
    if n < 98 then return c * ((1911 - 10 * n) // 3) // 500 end
    return c * (160 - n) // 100
  elseif rate == 2 then
    if n < 15 then return c * ((n + 1) // 3 + 24) // 50 end
    if n < 36 then return c * (n + 14) // 50 end
    return c * (n // 2 + 32) // 50
  elseif rate == 3 then
    return 6 * c // 5 - 15 * n * n + 100 * n - 140
  elseif rate == 4 then
    return 4 * c // 5
  elseif rate == 5 then
    return 5 * c // 4
  end
  return nil
end

-- Level (1..100) for an EXP value; nil when rate or exp are invalid.
function M.level_from_exp(rate, exp)
  if math.type(exp) ~= "integer" or exp < 0 then return nil end
  if M.exp_for_level(rate, 2) == nil then return nil end
  local level = 1
  for n = 2, 100 do
    if exp >= M.exp_for_level(rate, n) then level = n else break end
  end
  return level
end

return M

end
