      local list = darc.parse(s)
      if list then
        for _, f in ipairs(list) do
          if f.length >= 40 then
            local sub = s:sub(f.offset + 1, f.offset + f.length)
            local fw, fh = M.bclim_size(sub)
            if fw then add(id .. "/" .. f.path, fw, fh, sub) end
          end
        end
      end
    end
  end

  -- Decoded size announced by an LZ10/LZ11 header, or nil.
  local function lz_size(e)
    if #e < 8 then return nil end
    local n = string.unpack("<I3", e, 2)
    if n == 0 then n = string.unpack("<I4", e, 5) end
    return n
  end

  local function examine(e, id)
    local b = e:byte(1)
    if (b == 0x10 or b == 0x11) and #e > 4 and codec.lz_decompress then
      -- the header tells the decoded size: entries that cannot hold a candidate are not decompressed
      local n = lz_size(e)
      if #e <= M.MAX_LZ_INPUT and n and n >= M.MIN_DECODED and n <= M.MAX_LZ_OUTPUT then
        local out, status = garc_entry.decompress(codec, e, true)
        if status == "lz" then examine_plain(out, id) else reject("lz_failed " .. id) end
      end
      return
    end
    if #e >= M.MIN_DECODED then examine_plain(e, id) end
  end

  local function open_file(path)
    local d = uz.rom.romfs(path)
    if type(d) ~= "string" then reject("romfs_unreadable " .. path); return nil end
    local okg, g = false, nil
    if codec.garc and codec.garc_file then okg, g = pcall(codec.garc, d) end
    if okg and type(g) == "table" and type(g.count) == "number" and g.count >= 1 then
      return { path = path, data = d, garc = true, count = math.min(g.count, M.MAX_ENTRIES_PER_FILE), next = 1, g = g }
    end
    return { path = path, data = d, garc = false, count = 1, next = 1 }
  end

  -- One bounded batch of entries; `next` moves first, so a throwing entry is never retried.
  local function process(c)
    local last = math.min(c.next + M.ENTRIES_PER_STEP - 1, c.count)
    for i = c.next, last do
      c.next = i + 1
      stat.entries = stat.entries + 1
      local ok, err = pcall(function()
        local e = c.data
        if c.garc then
          local f = c.g.files and c.g.files[i] and c.g.files[i][1]
          if type(f) == "table" and type(f.length) == "number" and f.length < 40 then return end
          e = codec.garc_file(c.data, i, 1)
        end
        if type(e) == "string" and #e >= 40 then examine(e, c.path .. "#" .. i) end
      end)
      if not ok then
        stat.errors = stat.errors + 1
        reject("entry_error " .. c.path .. "#" .. i .. ": " .. tostring(err))
      end
    end
    return c.next > c.count
  end

  local function scan_dir(dir)
    local list = uz.rom.romfs_list(dir)
    if type(list) ~= "table" then reject("list_failed " .. dir); return end
    for _, e in ipairs(list) do
      local full = dir .. "/" .. tostring(e.name)
      if e.dir then
        dirs[#dirs + 1] = full
      elseif type(e.size) == "number" and e.size >= M.MIN_FILE_SIZE and e.size <= M.MAX_FILE_SIZE then
        files[#files + 1] = full
      end
    end
  end

  local function finish()
    table.sort(cands, function(a, b)
      local aa, ba = a.w * a.h, b.w * b.h
      if aa ~= ba then return aa > ba end
      return a.id < b.id
    end)
    state = "done"
    cur = nil
    save_index(true)
    if uz.log and uz.log.info then uz.log.info("map scan finished, " .. #cands .. " candidates") end
  end

  local function fail(why)
    state, cur, fail_reason = "failed", nil, short(why)
    save_index(false)
    if uz.log and uz.log.error then uz.log.error("map scan failed: " .. tostring(why)) end
  end

  -- One unit of work.
  local function advance()
    if state == "idle" then load_state() end
    if state == "idle" then return end
    if state == "dirs" then
      if #dirs > 0 then
        scan_dir(table.remove(dirs, 1))
      else
        table.sort(files)
        -- the forum-listed town map archives first, then the rest in path order
        local first, rest, is_prio = {}, {}, {}
        for _, p in ipairs(M.PRIORITY) do is_prio[p] = true end
        for _, p in ipairs(M.PRIORITY) do
          for _, f in ipairs(files) do if f == p then first[#first + 1] = f; break end end
        end
        for _, f in ipairs(files) do if not is_prio[f] then rest[#rest + 1] = f end end
        files = first
        for _, f in ipairs(rest) do files[#files + 1] = f end
        cwrite(M.FILES, table.concat(files, "\n") .. "\n")
        cwrite(M.PROGRESS, "0")
        fidx, state = 0, "files"
      end
    elseif state == "files" then
      if cur then
        if process(cur) then
          cur = nil
          fidx = fidx + 1
          if fidx % M.SAVE_EVERY == 0 then cwrite(M.PROGRESS, tostring(fidx)); save_index(false) end
        end
      elseif fidx >= #files then
        finish()
      else
        local path = files[fidx + 1]
        local ok, c = pcall(open_file, path)
        if not ok then
          reject("archive_error " .. path .. ": " .. tostring(c))
          stat.errors = stat.errors + 1
          c = nil
        end
        if c then cur = c else fidx = fidx + 1; stat.archives_skipped = stat.archives_skipped + 1 end
      end
    end
  end

  -- Restore the saved index/progress at once (cheap cache reads only).
  if state == "idle" then pcall(load_state) end

  local function terminal() return state == "done" or state == "failed" or state == "unsupported" end

  -- One bounded scan step: units until STEP_BUDGET_MS (uz.clock) is used. Never raises.
  function self.step()
    if terminal() then return end
    stat.steps = stat.steps + 1
    local t0 = clock()
    if t0 and not stat.started then stat.started = t0 end
    for _ = 1, M.MAX_UNITS_PER_STEP do
      local ok, err = pcall(advance)
      if not ok then
        -- advance() itself raised outside the per-entry/per-archive guards (directory listing, cache,
        -- sort): skip the work item that raised, never loop on it
        stat.errors = stat.errors + 1
        reject("scan_error: " .. tostring(err))
        if state == "dirs" then
          -- the directory was already taken from the queue
        elseif state == "files" then
          if cur then cur = nil end
          fidx = fidx + 1
          stat.archives_skipped = stat.archives_skipped + 1
        else
          fail("scan_error: " .. tostring(err))
        end
        if stat.errors > M.MAX_ERRORS then fail("too_many_errors") end
      end
      if terminal() then return end
      local now = clock()
      if now then
        stat.elapsed = now - (stat.started or now)
        if stat.elapsed > M.MAX_SCAN_MS then fail("time_limit"); return end
        if t0 and now - t0 >= M.STEP_BUDGET_MS then return end
      end
    end
  end

  function self.state() return state end
  function self.found() return (state == "done" or state == "failed") and #cands > 0 end

  function self.diagnostics()
    return {
      map_state = state,
      map_rev = M.CACHE_REV,
      map_archives_scanned = fidx,
      map_archives_total = #files,
      map_archives_skipped = stat.archives_skipped,
      map_dirs_pending = #dirs,
      map_entries_scanned = stat.entries,
      map_errors = stat.errors,
      map_candidates = #cands,
      map_current = cur and cur.path or "none",
      map_first_rejection = first_reject or "none",
      map_fail_reason = fail_reason or "none",
      map_steps = stat.steps,
      map_elapsed_ms = stat.elapsed,
    }
  end

  function self.candidates()
    if state == "unsupported" then return nil, "unsupported" end
    if not terminal() then self.step() end
    if state == "failed" and #cands == 0 then return nil, "unsupported" end
    if state ~= "done" and state ~= "failed" then return nil, "not_ready" end
    local out = {}
    for i = 1, math.min(#cands, M.LIST_CAP) do
      local c = cands[i]
      out[i] = { id = c.id, w = c.w, h = c.h }
    end
    return out
  end

  function self.image(id)
    if state == "unsupported" then return nil, "unsupported" end
    local path, entry, sub = M.parse_id(id)
    if not path then return nil, "unknown_map" end
    local key = "map/" .. hash(id .. "|" .. M.CACHE_REV) .. ".png"
    local hit = cread(key)
    if hit then
      if #hit > M.MAX_PNG then return nil, "too_large" end
      return hit
    end
    if state ~= "done" and state ~= "failed" then self.step(); return nil, "not_ready" end
    local known = false
    for _, c in ipairs(cands) do if c.id == id then known = true; break end end
    if not known then return nil, "unknown_map" end
    local d = uz.rom.romfs(path)
    if type(d) ~= "string" then return nil, "unknown_map" end
    local e = d
    local okg, g = false, nil
    if codec.garc then okg, g = pcall(codec.garc, d) end
    if okg and type(g) == "table" and type(g.count) == "number" and g.count >= 1 then
      e = codec.garc_file(d, entry, 1)
    end
    if type(e) ~= "string" then return nil, "unknown_map" end
    if not M.bclim_size(e) then
      local out, status = garc_entry.decompress(codec, e, true)
      if status == "lz_failed" then return nil, "unknown_map" end
      e = out
    end
    if sub then
      local list = darc.parse(e)
      local found
      for _, f in ipairs(list or {}) do if f.path == sub then found = f; break end end
      if not found then return nil, "unknown_map" end
      e = e:sub(found.offset + 1, found.offset + found.length)
    end
    local img = codec.bclim(e)
    if type(img) ~= "table" then return nil, "unknown_map" end
    local png = codec.png(img)
    if type(png) ~= "string" then return nil, "unknown_map" end
    if #png > M.MAX_PNG then return nil, "too_large" end
    cwrite(key, png)
    return png
  end

  function self.selected()
    local v = M.MAP_ID[game_id]
    if type(v) == "table" then v = v[revision_fn and revision_fn() or ""] end
    if type(v) == "string" then return v end
    return nil
  end

  return self
end

return M

end
__mod["gen6.moves"] = function(...)
-- Base PP per move, read at runtime from the user's own game files (RomFS move GARC). Nothing from the
-- game is shipped or persisted; the values live in a Lua table cache only.
--
-- ORAS move data (community-documented, all to verify locally, NOT yet checked on a real game):
--   path  : candidates "/a/1/8/9" (pk3DS GARCReference "move", recalled) and "/a/1/9/4", tried in order;
--           the first one whose data validates as a move table is used (see validate)
--   entry : 0x24 bytes per move (PKHeX Move6), index = move id; byte 0 type, 3 power, 4 accuracy,
--           0x05 base PP (recalled), 0x06 priority
--   shape : a "WD" mini container (u16 count, count + 1 u32 offsets) inside the single GARC file, or the
--           concatenated table (length % 0x24 == 0), or one GARC file per move
local garc_entry = require("gen6.garc_entry")
local M = {}

M.CANDIDATE_PATHS = { "/a/1/8/9", "/a/1/9/4" }
M.ENTRY_SIZE = 0x24
M.PP_OFFSET = 0x05
M.MIN_ENTRIES = 622 -- moves 0..621 (ORAS)
M.MAX_BASE_PP = 64
M.MAX_ATTEMPTS = 3

function M.new(uz, opts)
  opts = opts or {}
  local paths = opts.paths or M.CANDIDATE_PATHS
  local esize = opts.entry_size or M.ENTRY_SIZE
  local poff = opts.pp_offset or M.PP_OFFSET
  local self = {}
  local pps, attempts = nil, 0
  local first_reject
  local function reject(why) if not first_reject then first_reject = why end end

  -- entries: list (1-based, entry i = move i - 1) of strings -> table move id -> base PP, or nil
  local function from_entries(list)
    if #list < M.MIN_ENTRIES then return nil end
    local out, filled = {}, 0
    for id = 1, M.MIN_ENTRIES - 1 do
      local e = list[id + 1]
      if type(e) ~= "string" or #e ~= esize then reject("entry_size"); return nil end
      local pp = e:byte(poff + 1)
      if pp > M.MAX_BASE_PP then reject("pp_invalid"); return nil end
      if pp > 0 then filled = filled + 1 end
      out[id] = pp
    end
    if filled < (M.MIN_ENTRIES - 1) * 9 // 10 then reject("pp_mostly_zero"); return nil end
    return out
  end

  local function split(blob)
    local list = {}
    if blob:sub(1, 2) == "WD" and #blob >= 8 then -- mini container
      local count = string.unpack("<I2", blob, 3)
      if 4 + 4 * (count + 1) > #blob then return nil end
      local offs = {}
      for i = 0, count do offs[i] = string.unpack("<I4", blob, 5 + 4 * i) end
      for i = 0, count - 1 do
        if offs[i] > offs[i + 1] or offs[i + 1] > #blob then return nil end
        list[i + 1] = blob:sub(offs[i] + 1, offs[i + 1])
      end
      return list
    end
    if #blob % esize == 0 then
      for i = 0, #blob // esize - 1 do list[i + 1] = blob:sub(i * esize + 1, i * esize + esize) end
      return list
    end
    return nil
  end

  local function validate(data)
    local g, gerr = uz.codec.garc(data)
    if type(g) ~= "table" or type(g.count) ~= "number" then
      reject("garc_rejected: " .. (tostring(gerr):gsub("[^%w _%.:%-]", "?"):sub(1, 40)))
      return nil
    end
    local last = garc_entry.entry(uz.codec, data, g.count)
    if type(last) == "string" then
      local list = split(last)
      local r = list and from_entries(list)
      if r then return r end
    end
    if g.count >= M.MIN_ENTRIES then
      local list = {}
      for i = 1, M.MIN_ENTRIES do list[i] = garc_entry.entry(uz.codec, data, i) end
      return from_entries(list)
    end
    reject("table_shape")
    return nil
  end

  local function load()
    if pps then return true end
    if attempts >= M.MAX_ATTEMPTS then return false end
    attempts = attempts + 1
    if not (uz and uz.rom and uz.rom.romfs and uz.codec and uz.codec.garc and uz.codec.garc_file) then return false end
    for _, path in ipairs(paths) do
      local data = uz.rom.romfs(path)
      if type(data) ~= "string" then reject("romfs_unreadable") else
        local r = validate(data)
        if r then
          pps = r
          self.path = path
          if uz.log and uz.log.info then uz.log.info("move data accepted at " .. path) end
          return true
        end
      end
    end
    return false
  end

  -- Base PP (1..64) of a move id (1..621), or nil when unknown or the table is not readable.
  function self.base_pp(move)
    if math.type(move) ~= "integer" or move < 1 or move >= M.MIN_ENTRIES then return nil end
    if not load() then return nil end
    local pp = pps[move]
    return (pp and pp > 0) and pp or nil
  end

  function self.diagnostics()
    return { moves_ok = pps and 1 or 0, moves_attempts = attempts, moves_first_rejection = first_reject or "none" }
  end

  function self.reset() pps, attempts, self.path = nil, 0, nil end

  return self
end

return M

end
__mod["gen6.oras"] = function(...)
-- Adapter for Pokemon Omega Ruby / Alpha Sapphire (3DS, Gen 6).
-- Addresses and formats with sources: docs/games/omega-ruby-alpha-sapphire.md.
-- Backs team (with live stats), boxes, trainer, badges, location, battle, encounters, names
-- (game text), zones/areas/locations (encdata), species_info (personal), icons and the region map.
local pk6 = require("gen6.pk6")
local growth = require("gen6.growth")
local personal = require("gen6.personal")
local moves = require("gen6.moves")
local icons = require("gen6.icons")
local maps = require("gen6.maps")
local addr = require("gen6.oras_addr")
local text = require("gen6.text")
local zones = require("gen6.zones")
local oras_battle = require("gen6.oras_battle")
local pk6_edit = require("gen6.pk6_edit")

local M = {}

M.PARTY_SLOTS = addr.PARTY_SLOTS
M.PARTY_STRIDE = addr.PARTY_STRIDE -- 0x1E4: encrypted PK6 (0xE8) at +0, encrypted party stats (22 bytes) at +0x158
M.STATS_OFFSET, M.STATS_LEN = 0x158, 22
M.PARTY_SIZE = pk6.SIZE_PARTY
M.BOX_COUNT = addr.BOX_COUNT
M.BOX_SLOTS = addr.BOX_SLOTS
M.BOX_SIZE = addr.BOX_SIZE
M.REVISIONS = addr.REVISIONS
M.NAME_START_TICK, M.NAME_STEP_EVERY = 20, 4   -- game text loading (ticks % 4 == 2)
M.ZONE_START_TICK, M.ZONE_STEP_EVERY = 30, 4   -- zone scan (ticks % 4 == 1)
M.ICON_START_TICK = 90 -- ticks before icon discovery starts
M.ICON_STEP_EVERY = 8  -- ticks between discovery steps
M.MAP_START_TICK = 120 -- map scan starts later; steps are offset from the other loaders
M.MAP_STEP_EVERY = 4 -- ticks % 4 == 3 (names 2, zones 1, icons 0 mod 8); a step is time-budgeted (maps.STEP_BUDGET_MS)
M.PERSONAL_START_TICK, M.PERSONAL_STEP_EVERY = 60, 30 -- personal table (growth, types) is loaded in the background
M.DETECT_EVERY = 5
M.CROSSCHECK_EVERY = 30
M.BADGE_POLL_EVERY = 15
M.ORIGIN_AS, M.ORIGIN_OR = 26, 27 -- PKHeX GameVersion (X 24, Y 25)
M.MAX_MONEY = 999999
M.MAX_STAT = 1500 -- upper bound for a stat or HP value (Blissey at level 100: 714)

-- MyStatus block offsets (PKHeX MyStatus6). Checked against
-- https://raw.githubusercontent.com/kwsch/PKHeX/master/PKHeX.Core/Saves/Substructures/Gen6/MyStatus6.cs :
-- TID16 +0, SID16 +2, Game +4, Region +0x26, Country +0x27, ConsoleRegion +0x2C, Language +0x2D
-- (LanguageID: 1 ja, 2 en, 3 fr, 4 it, 5 de, 7 es, 8 ko, 9 zh-Hans, 10 zh-Hant), OT name +0x48 (0x1A bytes).
local MS_TID, MS_VERSION, MS_LANGUAGE, MS_OT = 0, 4, 0x2D, 0x48
-- Misc block offsets (PKHeX Misc6AO)
local MISC_MONEY, MISC_BADGES = 8, 0xC

-- Items pouch: Poke Ball item ids (PKHeX Legal ball items, recalled, not re-fetched): 1..16 (Master
-- to Cherish), 492..500 (Fast to Park), 576 (Dream). Sanity limits: PKHeX max item id 775, count 999.
M.BALL_IDS = { [576] = true }
for i = 1, 16 do M.BALL_IDS[i] = true end
for i = 492, 500 do M.BALL_IDS[i] = true end
M.MAX_ITEM_ID, M.MAX_ITEM_COUNT = 775, 999

-- Sanity of decrypted party stats (garbage decrypts almost never pass; an all-zero area decrypts to
-- garbage): level 1..100, 0 < max HP, HP <= max HP, every battle stat plausible.
function M.live_sane(x)
  if x.level < 1 or x.level > 100 or x.max_hp < 1 or x.max_hp > M.MAX_STAT or x.hp > x.max_hp then return false end
  for _, v in pairs(x.stats) do
    if v < 1 or v > M.MAX_STAT then return false end
  end
  return true
end

local function popcount(v)
  local n = 0
  while v ~= 0 do n = n + (v & 1); v = v >> 1 end
