  -- MyStatus block: { name, tid, sid, version, language_id, language } or nil.
  local function mystatus()
    local base = A("mystatus")
    local raw = base and uz.memory.bytes(base, 0x70)
    if not raw or #raw < 0x70 then return nil end
    local tid, sid = string.unpack("<I2I2", raw, MS_TID + 1)
    local lang_id = raw:byte(MS_LANGUAGE + 1)
    return {
      name = pk6.utf16le_to_utf8(raw:sub(MS_OT + 1, MS_OT + 0x1A), 12),
      tid = tid, sid = sid, version = raw:byte(MS_VERSION + 1),
      language_id = lang_id, language = pk6.LANGUAGES[lang_id],
    }
  end

  -- Own-origin party members must carry the trainer's TID, otherwise the revision (or the MyStatus
  -- address) is wrong. Runs until it had something to compare, logs a warning on a mismatch.
  local function crosscheck(team)
    if checked or not chosen then return end
    local ms = mystatus()
    if not ms or ms.name == "" then return end
    local cands, match = 0, false
    for _, r in ipairs(team) do
      if r.origin_game == M.ORIGIN_AS or r.origin_game == M.ORIGIN_OR then
        cands = cands + 1
        if r.ot_id == ms.tid then match = true end
      end
    end
    if cands == 0 then return end
    checked = true
    if not match then
      warn_once("crosscheck", "revision cross-check failed: MyStatus TID " .. ms.tid ..
        " matches no own party member; revision " .. chosen.name .. " or the mystatus address may be wrong")
    end
  end

  local function read_team()
    local set = detect()
    if not set then return nil end
    local out = {}
    for i = 1, M.PARTY_SLOTS do
      local rec, live = read_party_slot(set.a.party + (i - 1) * M.PARTY_STRIDE)
      if rec then
        rec.slot = i
        if live then live_seen = true end
        out[#out + 1] = finish(rec)
      end
    end
    return out
  end

  local obj = {}

  -- Language of the game and where it came from: "mystatus" (language byte), "party" (largest own-origin
  -- OT group) or nil, "fallback" (not known yet; callers must not guess from region or title).
  local function resolve_language()
    local ms = mystatus()
    if ms and ms.language then return ms.language, "mystatus" end
    local team = read_team()
    if not team then return nil, "fallback" end
    local groups, order = {}, {}
    for _, r in ipairs(team) do
      if (r.origin_game == M.ORIGIN_AS or r.origin_game == M.ORIGIN_OR) and r.language then
        local key = r.ot_id .. ":" .. r.ot_sid
        if not groups[key] then groups[key] = { n = 0, first = r }; order[#order + 1] = key end
        groups[key].n = groups[key].n + 1
      end
    end
    local best
    for _, key in ipairs(order) do
      if not best or groups[key].n > best.n then best = groups[key] end
    end
    if best and best.first.language then return best.first.language, "party" end
    return nil, "fallback"
  end

  function obj:language()
    return (resolve_language())
  end

  names = text.new(uz, { language_fn = function() return obj:language() end })
  zone_store = zones.new(uz, {
    name = function(kind, id) return names.peek(kind, id) end,
    names_state = function() return names.state() end,
  })
  map_store = maps.new(uz, ctx.game and ctx.game.id, function() return chosen and chosen.name end)

  function obj:revision()
    local set = detect()
    if not set then return nil, "not_ready" end
    return set.name
  end

  local function location_info(quiet)
    local set = detect()
    if not set then return nil, "not_ready" end
    local a = A("map_id")
    if not a then return nil, "unsupported" end
    local zone = u16(a)
    if zone == nil then return nil, "not_ready" end
    local out = { zone = zone, source = "memory", x = f32(A("player_x")), y = f32(A("player_y")) }
    local zi = zone_store.zone_info(zone, quiet)
    if zi then out.location, out.name = zi.location, zi.name end
    return out
  end

  local function poll()
    if not chosen then return end
    local loc = location_info(true)
    if loc then
      local key = loc.zone .. ":" .. tostring(loc.location) .. ":" .. tostring(loc.name)
      if key ~= last_loc_key then
        last_loc_key = key
        uz.events.emit("location.changed", loc)
      end
    end
    if ticks % M.BADGE_POLL_EVERY == 0 then
      local misc = A("misc")
      local b = misc and uz.memory.u8(misc + MISC_BADGES)
      if b then
        if last_badges ~= nil and b ~= last_badges then
          local new = {}
          for i = 1, 8 do
            if (b >> (i - 1)) & 1 == 1 and (last_badges >> (i - 1)) & 1 == 0 then new[#new + 1] = i end
          end
          uz.events.emit("badges.changed", { count = popcount(b), new = new })
        end
        last_badges = b
      end
    end
    if battle_mod then battle_mod.poll() end
    if not checked and ticks % M.CROSSCHECK_EVERY == 0 then
      local team = read_team()
      if team then crosscheck(team) end
    end
  end

  local function position()
    return u16(A("map_id")), f32(A("player_x")), f32(A("player_y"))
  end

  battle_mod = oras_battle.new(uz, {
    addr = A,
    read_slot = function(base)
      local rec = read_party_slot(base)
      if rec then rec = finish(rec) end
      return rec
    end,
    position = position,
    species_name = function(species) return peek_name("species", species) end,
    team = read_team,
    location_id = function(zone)
      local zi = zone_store.zone_info(zone, true)
      return zi and zi.location or nil
    end,
  })

  -- Called every tick by main.lua: bounded background work and the state tracking.
  function obj:tick()
    ticks = ticks + 1
    if not chosen and ticks % M.DETECT_EVERY == 0 then detect() end
    if ticks >= M.NAME_START_TICK and ticks % M.NAME_STEP_EVERY == 2 then names.step() end
    if ticks >= M.ZONE_START_TICK and ticks % M.ZONE_STEP_EVERY == 1 then zone_store.step() end
    if ticks >= M.PERSONAL_START_TICK and ticks % M.PERSONAL_STEP_EVERY == 0 then pers.growth_rate(1) end
    if ticks >= M.MAP_START_TICK and ticks % M.MAP_STEP_EVERY == 3 then
      map_store.step()
    end
    if ticks >= M.ICON_START_TICK and ticks % M.ICON_STEP_EVERY == 0 and icon_store.state() ~= "done" then
      icon_store.step()
    end
    if icon_store.state() ~= "idle" and icon_store.state() ~= "scan" and not icon_store.export_done() then
      icon_store.export_step(function()
        local team = chosen and read_team()
        local out = {}
        for _, r in ipairs(team or {}) do out[#out + 1] = r.species end
        return out
      end)
    end
    local ok, err = pcall(poll)
    if not ok then warn_once("poll", "tracking failed: " .. tostring(err)) end
  end

  -- Feature overrides: depend on runtime state (icons found, names loaded, ...).
  function obj:features()
    local any_map, any_battle = false, false
    for _, set in ipairs(sets) do
      if set.a.map_id then any_map = true end
      if set.a.battle_wild_foes or set.a.battle_trainer_foes then any_battle = true end
    end
    return {
      icons = icon_store.found(), map = map_store.found(), names = names.ready(), areas = zone_store.found(),
      locations = zone_store.has_locations() or (zone_store.state() ~= "idle" and zone_store.state() ~= "scan" and
        names.count("location") > 0),
      live_stats = live_seen, location = chosen and A("map_id") ~= nil or (not chosen and any_map),
      battle = chosen and battle_mod.available() or (not chosen and any_battle),
      encounters = chosen and battle_mod.available() or (not chosen and any_battle),
    }
  end

  function obj:icon_rev() return icon_store.icon_rev() end
  function obj:icon(species, form) return icon_store.icon(species, form) end
  function obj:icon_variants(species, form) return icon_store.icon_variants(species, form) end
  function obj:map_candidates() return map_store.candidates() end
  function obj:map_image(id) return map_store.image(id) end
  function obj:map_selected() return map_store.selected() end

  function obj:name(kind, id) return names.name(kind, id) end
  function obj:areas() return zone_store.areas() end

  -- Places for a picker. The zone scan is the source; when it is unsupported, failed or found no
  -- location, every non-empty entry of the game's location text is listed instead (source = "text",
  -- no zones, no encounter flag). A list is only returned together with its names.
  function obj:locations()
    local list, why = zone_store.locations()
    if list and #list > 0 then
      for _, l in ipairs(list) do l.source = "zones" end
      list.source = "zones"
      return list
    end
    if why == "not_ready" then return nil, why end
    -- the zone scan is over (done empty, unsupported) or failing (retrying): use the text
    local tl, twhy = names.list("location")
    if not tl then return nil, twhy == "no_lines" and "unsupported" or twhy end
    local out = { source = "text" }
    for i, e in ipairs(tl) do
      out[i] = { id = e.id, name = e.name, zones = {}, has_encounters = false, source = "text" }
    end
    return out
  end

  function obj:diagnostics()
    local d = zone_store.diagnostics()
    for k, v in pairs(names.diagnostics()) do d[k] = v end
    for k, v in pairs(pers.diagnostics()) do d[k] = v end
    for k, v in pairs(move_store.diagnostics()) do d[k] = v end
    for k, v in pairs(icon_store.diagnostics()) do d[k] = v end
    for k, v in pairs(map_store.diagnostics()) do d[k] = v end
    d.locations_source = d.locations > 0 and "zones" or (names.count("location") > 0 and "text" or "none")
    d.revision = chosen and chosen.name or "none"
    local ok, lang, src = pcall(resolve_language)
    d.language = ok and lang or "unknown"
    d.language_source = ok and src or "fallback"
    -- raw MyStatus bytes help to diagnose an unreadable language (-1: block not readable)
    local base = A("mystatus")
    local raw = base and uz.memory.bytes(base, 0x70)
    d.mystatus_language_id = raw and #raw >= 0x70 and raw:byte(MS_LANGUAGE + 1) or -1
    return d
  end
  function obj:zone_info(zone) return zone_store.zone_info(zone) end

  function obj:species_info(species, form)
    if not pers.growth_rate(1) then return nil, "not_ready" end
    return pers.info(species, form or 0)
  end

  -- Abilities of a species form: { {slot = 1, id, name}, {slot = 2, ...}, {slot = 3, hidden = true, ...} }.
  -- Slot 2 is left out when the species has one ability (none or the same id); the hidden slot when absent.
  function obj:abilities(species, form)
    if not pers.growth_rate(1) then return nil, "not_ready" end
    local ab, err = pers.abilities(species, form or 0)
    if not ab then return nil, err end
    local out = {}
    for s = 1, 3 do
      local id = ab[s]
      if id ~= 0 and not (s == 2 and id == ab[1]) then
        out[#out + 1] = { slot = s, id = id, name = peek_name("ability", id), hidden = s == 3 or nil }
      end
    end
    return out
  end

  function obj:location() return location_info(false) end

  function obj:team()
    local team = read_team()
    if not team then return nil, "not_ready" end
    crosscheck(team)
    return team
  end

  function obj:trainer()
    local set = detect()
    if not set then return nil, "not_ready" end
    local ms = mystatus()
    if not ms or ms.name == "" then return nil, "not_ready" end
    local out = {
      name = ms.name, tid = ms.tid, sid = ms.sid, version = ms.version, language = ms.language,
    }
    local misc = A("misc")
    if misc then
      local money = uz.memory.u32(misc + MISC_MONEY)
      if money and money <= M.MAX_MONEY then out.money = money end
      local b = uz.memory.u8(misc + MISC_BADGES)
      if b then out.badges = popcount(b) end
    end
    local pt = A("play_time")
    local raw = pt and uz.memory.bytes(pt, 4)
    if raw and #raw == 4 then
      local h, m, s = string.unpack("<I2I1I1", raw)
      if m < 60 and s < 60 then out.play_time = { h = h, m = m, s = s } end
    end
    return out
  end

  function obj:badges()
    local set = detect()
    if not set then return nil, "not_ready" end
    local misc = A("misc")
    if not misc then return nil, "unsupported" end
    local b = uz.memory.u8(misc + MISC_BADGES)
    if b == nil then return nil, "not_ready" end
    local flags = {}
    for i = 1, 8 do flags[i] = (b >> (i - 1)) & 1 == 1 end
    return { count = popcount(b), flags = flags }
  end

  -- Poke Ball count in the Items pouch (400 slots of u16 id, u16 count, packed from slot 0).
  function obj:balls()
    if not detect() then return nil, "not_ready" end
    local bag = A("bag")
    if not bag then return nil, "unsupported" end
    local raw = uz.memory.bytes(bag, addr.BAG_SLOTS * 4)
    if not raw or #raw < addr.BAG_SLOTS * 4 then return nil, "not_ready" end
    local valid, invalid, balls = 0, 0, 0
    for i = 0, addr.BAG_SLOTS - 1 do
      local id, ct = string.unpack("<I2I2", raw, i * 4 + 1)
      if id == 0 then break end -- the pouch is packed, the first empty slot ends it
      if id > M.MAX_ITEM_ID or ct == 0 or ct > M.MAX_ITEM_COUNT then
        invalid = invalid + 1
      else
        valid = valid + 1
        if M.BALL_IDS[id] then balls = balls + ct end
      end
    end
    -- Mostly implausible slots: wrong address or stale memory, better no answer than a wrong number.
    if invalid > 0 and invalid >= valid then return nil, "unsupported" end
    return { count = balls }
  end

  -- Reads one pouch as a packed list { {id, count}, ... } (ends at the first empty slot, invalid slots are
  -- kept raw). Returns list, nil | nil, "not_ready" | nil, "unsupported" (garbage).
  local function read_pouch(bagaddr, p)
    local raw = uz.memory.bytes(bagaddr + p.off, p.slots * 4)
    if not raw or #raw < p.slots * 4 then return nil, "not_ready" end
    local list, valid, invalid = {}, 0, 0
    for i = 0, p.slots - 1 do
      local id, ct = string.unpack("<I2I2", raw, i * 4 + 1)
      if id == 0 then break end
      list[#list + 1] = { id, ct }
      if id > M.MAX_ITEM_ID or ct == 0 or ct > p.max_count then invalid = invalid + 1 else valid = valid + 1 end
    end
    if invalid > 0 and invalid >= valid then return nil, "unsupported" end
    return list
  end

  -- All pouches: { items = { {slot, item, count, name}, ... }, key_items, tms, medicine, berries }. The Items
  -- pouch must be readable and plausible; another pouch that is not is left out. Implausible slots are skipped.
  function obj:bag()
    if not detect() then return nil, "not_ready" end
    local bagaddr = A("bag")
    if not bagaddr then return nil, "unsupported" end
    local out = {}
    for _, p in ipairs(addr.POUCHES) do
      local list, err = read_pouch(bagaddr, p)
      if not list then
        if p.name == "items" then return nil, err end
      else
        local rows = {}
        for i, s in ipairs(list) do
          if s[1] <= M.MAX_ITEM_ID and s[2] >= 1 and s[2] <= p.max_count then
            rows[#rows + 1] = { slot = i, item = s[1], count = s[2], name = peek_name("item", s[1]) }
          end
        end
        out[p.name] = rows
      end
    end
    return out
  end

  -- Event flag n (0..0xCFF) of the save, or nil. Not part of the interface yet.
  function obj:event_flag(n)
    if not detect() then return nil end
    local base = A("event_flags")
    if not base or math.type(n) ~= "integer" or n < 0 or n >= 0xD00 then return nil end
    local b = uz.memory.u8(base + (n >> 3))
    if b == nil then return nil end
    return (b >> (n & 7)) & 1 == 1
  end

  function obj:battle()
    if not detect() then return nil, "not_ready" end
    if not battle_mod.available() then return nil, "unsupported" end
    local b = battle_mod.battle()
    if b.active then
      for _, f in ipairs(b.foes) do f.species_name = peek_name("species", f.species) end
      for _, o in ipairs(b.own) do o.species_name = peek_name("species", o.species) end
    end
    return b
  end

  function obj:encounters()
    if not detect() then return nil, "not_ready" end
    if not battle_mod.available() then return nil, "unsupported" end
    local list = battle_mod.encounters()
    for _, e in ipairs(list) do e.species_name = peek_name("species", e.species) end
    return list
  end

  -- ---- write helpers (build write operations only, nothing is written here) ----

  function obj:edit_limits()
    local L = pk6_edit.LIMITS
    local out = {}
    for k, v in pairs(L) do out[k] = v end
    out.money = M.MAX_MONEY
    out.team_slots, out.boxes, out.box_slots = M.PARTY_SLOTS, M.BOX_COUNT, M.BOX_SLOTS
    out.item_count = M.MAX_ITEM_COUNT
    out.pouches = {}
    for _, p in ipairs(addr.POUCHES) do out.pouches[p.name] = { slots = p.slots, max_count = p.max_count } end
    return out
  end

  function obj:names_list(kind)
    return names.list(kind)
  end

  -- Location: { kind = "team", slot = 1..6 } or { kind = "box", box = 1..31, slot = 1..30 }.
  -- Returns { addr, bytes, ops = { {addr, bytes}, ... }, warnings = { ... }, record = <new record> }:
  -- apply every op of `ops` in order with uz.memory.write. `addr`/`bytes` are the first op. Errors:
  -- nil, "not_ready" | "invalid_location" | "empty_slot" | "growth_unavailable" | "invalid_<field>" |
  -- "ev_total" | "unknown_field:<name>".
  function obj:encode_pokemon(location, fields)
    local set = detect()
    if not set then return nil, "not_ready" end
    if type(location) ~= "table" or type(fields) ~= "table" then return nil, "invalid_location" end
    local base, size, live_ext, ext_raw
    local plain, ok
    if location.kind == "team" then
      local slot = location.slot
      if not (math.type(slot) == "integer" and slot >= 1 and slot <= M.PARTY_SLOTS) then return nil, "invalid_location" end
      base = set.a.party + (slot - 1) * M.PARTY_STRIDE
      local raw = uz.memory.bytes(base, 0xE8)
      if not raw or #raw < 0xE8 then return nil, "not_ready" end
      ext_raw = uz.memory.bytes(base + M.STATS_OFFSET, M.STATS_LEN)
      if ext_raw and #ext_raw == M.STATS_LEN then
        local p2, ok2 = pk6.decrypt(raw .. ext_raw .. string.rep("\0", pk6.SIZE_PARTY - 0xE8 - M.STATS_LEN))
        local r2 = ok2 and pk6.parse(p2)
        if r2 and r2.party_ext and M.live_sane(r2.party_ext) then plain, ok, live_ext = p2, ok2, true end
      end
      if not plain then plain, ok = pk6.decrypt(raw .. string.rep("\0", 232 - 0xE8)) end
      size = 0xE8
    elseif location.kind == "box" then
      local b, s = location.box, location.slot
      if not (math.type(b) == "integer" and b >= 1 and b <= M.BOX_COUNT and math.type(s) == "integer" and s >= 1 and
        s <= M.BOX_SLOTS) then
        return nil, "invalid_location"
      end
      base = set.a.box + ((b - 1) * M.BOX_SLOTS + (s - 1)) * M.BOX_SIZE
      local raw = uz.memory.bytes(base, M.BOX_SIZE)
      if not raw or #raw < M.BOX_SIZE then return nil, "not_ready" end
      plain, ok = pk6.decrypt(raw)
      size = M.BOX_SIZE
    else
      return nil, "invalid_location"
    end
    local rec = ok and pk6.parse(plain)
    if not rec or rec.species < 1 or rec.species > pk6.MAX_SPECIES then return nil, "empty_slot" end
    local level
    if live_ext then level = rec.party_ext.level else
      local rate = pers.growth_rate(rec.species)
      level = rate and growth.level_from_exp(rate, rec.exp) or nil
    end
    local new, warnings = pk6_edit.apply(plain, fields, {
      growth_rate = pers.growth_rate,
      base_stats = function(sp, form)
        return (pers.base_stats(sp, form))
      end,
      species_name = function(id) return peek_name("species", id) end,
      current_level = level,
      move_pp = move_store.base_pp,
      abilities = function(sp, form)
        return (pers.abilities(sp, form))
      end,
    })
    if not new then return nil, warnings end
    local enc = pk6.seal(new)
    local ops = { { addr = base, bytes = enc:sub(1, size) } }
    if live_ext then ops[2] = { addr = base + M.STATS_OFFSET, bytes = enc:sub(0xE9, 0xE8 + M.STATS_LEN) } end
    local record = pk6.parse(new)
    if record and not live_ext then record.party_ext = nil end
    return { addr = ops[1].addr, bytes = ops[1].bytes, ops = ops, warnings = warnings, record = record }
  end

  -- Money (0..999999) at misc + 8.
  function obj:encode_money(value)
    local set = detect()
    if not set then return nil, "not_ready" end
    if not (math.type(value) == "integer" and value >= 0 and value <= M.MAX_MONEY) then return nil, "invalid_money" end
    local misc = A("misc")
    if not misc then return nil, "unsupported" end
    local bytes = string.pack("<I4", value)
    return { addr = misc + MISC_MONEY, bytes = bytes, ops = { { addr = misc + MISC_MONEY, bytes = bytes } }, warnings = {} }
  end

  -- Bag slot: encode_item(pouch, item, count [, slot]). pouch: "items" | "key_items" | "tms" | "medicine" |
  -- "berries"; item 1..775; count 0..max of the pouch (999, key items and TMs 1); count 0 removes the item.
  -- Pouches are treated as packed lists (an empty slot ends the list). Without `slot` the item's slot is
  -- changed or the item is appended; with `slot` (1-based, at most one past the last used slot) that slot is
  -- set to item/count. Returns { addr, bytes, ops, warnings, pouch, slot } (ops cover the changed slots only;
  -- an unchanged bag gives one op rewriting the slot and the warning "unchanged"). Errors: nil, "not_ready" |
  -- "unsupported" | "unknown_pouch" | "invalid_item" | "invalid_count" | "invalid_slot" | "pouch_full".
  function obj:encode_item(pouch, item, count, slot)
    if not detect() then return nil, "not_ready" end
    local p = type(pouch) == "string" and addr.POUCH[pouch] or nil
    if not p then return nil, "unknown_pouch" end
    if not (math.type(item) == "integer" and item >= 1 and item <= M.MAX_ITEM_ID) then return nil, "invalid_item" end
    if not (math.type(count) == "integer" and count >= 0 and count <= p.max_count) then return nil, "invalid_count" end
    if slot ~= nil and not (math.type(slot) == "integer" and slot >= 1 and slot <= p.slots) then
      return nil, "invalid_slot"
    end
    local bagaddr = A("bag")
    if not bagaddr then return nil, "unsupported" end
    local list, err = read_pouch(bagaddr, p)
    if not list then return nil, err end
    local old = {}
    for i, s in ipairs(list) do old[i] = s end
    local at = slot
    if slot then
      if slot > #list + 1 then return nil, "invalid_slot" end
      if count == 0 then
        if slot > #list then return nil, "invalid_slot" end
        table.remove(list, slot)
      else
        list[slot] = { item, count }
      end
    else
      for i, s in ipairs(list) do
        if s[1] == item then at = i; break end
      end
      if count == 0 then
        if at then table.remove(list, at) end
      elseif at then
        list[at] = { item, count }
      else
        if #list >= p.slots then return nil, "pouch_full" end
        list[#list + 1] = { item, count }
        at = #list
      end
    end
    local first, last
    for i = 1, p.slots do
      local a, b = old[i], list[i]
      if (a and a[1] or 0) ~= (b and b[1] or 0) or (a and a[2] or 0) ~= (b and b[2] or 0) then
        first = first or i
        last = i
      end
    end
    local warnings = {}
    if not first then first, last = at or 1, at or 1; warnings[1] = "unchanged" end
    local parts = {}
    for i = first, last do
      local s = list[i]
      parts[#parts + 1] = string.pack("<I2I2", s and s[1] or 0, s and s[2] or 0)
    end
    local op = { addr = bagaddr + p.off + (first - 1) * 4, bytes = table.concat(parts) }
    return { addr = op.addr, bytes = op.bytes, ops = { op }, warnings = warnings, pouch = pouch, slot = at }
  end

  function obj:box_count()
    if not detect() then return nil, "not_ready" end
    return M.BOX_COUNT
  end

  function obj:box(n)
    local set = detect()
    if not set then return nil, "not_ready" end
    if math.type(n) ~= "integer" or n < 1 or n > M.BOX_COUNT then return nil, "out_of_range" end
    local base = set.a.box + (n - 1) * M.BOX_SLOTS * M.BOX_SIZE
    if not uz.memory.bytes(base, M.BOX_SLOTS * M.BOX_SIZE) then return nil, "not_ready" end
    local out = {}
    for s = 1, M.BOX_SLOTS do
      local rec = read_record(base + (s - 1) * M.BOX_SIZE, M.BOX_SIZE)
      if rec then rec.slot = s; rec.box = n; out[#out + 1] = finish(rec) end
    end
    return out
  end

  return obj
end

return M

end
__mod["gen6.oras_addr"] = function(...)
-- Address tables of Omega Ruby / Alpha Sapphire per game revision, and the address overrides.
-- Every value and its source: docs/games/omega-ruby-alpha-sapphire.md. A nil entry means "no
-- address known" (reported as open, never guessed).
--
-- Revisions are game versions (update patches), not regions: "v1.0" (no update) and "v1.4"
-- (final update). Inside the save-data range 0x08C6xxxx-0x08CFxxxx v1.4 = v1.0 + 0x3FF0.
local M = {}

M.SHIFT = 0x3FF0
M.OVERRIDE_FILE = "config/addresses.txt"
M.ZONE_OVERRIDE_FILE = "config/zone_addr.txt" -- older single override, equals the key map_id

-- Layout constants shared by adapter and tests.
M.PARTY_STRIDE = 0x1E4
M.PARTY_SLOTS = 6
M.BOX_COUNT, M.BOX_SLOTS, M.BOX_SIZE = 31, 30, 232
M.MON_STRIDE, M.MON_SLOTS = 0x244, 8
M.FLAG_BATTLE = 0x00040001
M.BAG_SLOTS = 400 -- Items pouch (Poke Balls live here)
-- Bag pouches, offsets relative to the bag start (= the Items pouch), each slot u16 item id + u16 count.
-- PKHeX SAV6AO / MyItem layout (recalled, not re-fetched; not checked on a real game). The order is the
-- order of bag().
M.POUCHES = {
  { name = "items", off = 0x000, slots = 400, max_count = 999 },
  { name = "key_items", off = 0x640, slots = 96, max_count = 1 },
  { name = "tms", off = 0x7C0, slots = 108, max_count = 1 },
  { name = "medicine", off = 0x970, slots = 64, max_count = 999 },
  { name = "berries", off = 0xA70, slots = 72, max_count = 999 },
}
M.POUCH = {}
for _, p in ipairs(M.POUCHES) do M.POUCH[p.name] = p end
M.BAG_BYTES = 0xA70 + 72 * 4 -- whole bag, 0xB90

-- key -> watched length in bytes
M.LENGTHS = {
  party = M.PARTY_SLOTS * M.PARTY_STRIDE,
  box = M.BOX_COUNT * M.BOX_SLOTS * M.BOX_SIZE,
  mystatus = 0x70,   -- TID +0, SID +2, version +4, language +0x2D, OT name +0x48 (0x1A bytes)
  misc = 0x10,       -- money u32 +8, badges u8 bitfield +0xC
  bag = M.BAG_BYTES, -- all 5 pouches, first the Items pouch: 400 slots x (u16 item id, u16 count)
  play_time = 4,     -- u16 hours, u8 minutes, u8 seconds
  map_id = 4,        -- u16 zone id, u16 facing
  player_x = 4,      -- f32
  player_y = 4,      -- f32
  event_flags = 0x1A0, -- 0xD00 flag bits
  battle_flag = 4,   -- u32, == FLAG_BATTLE while in battle (v1.4 only)
  battle_wild_foes = M.PARTY_SLOTS * M.PARTY_STRIDE,
  battle_trainer_foes = M.PARTY_SLOTS * M.PARTY_STRIDE,
  battle_wild_mons = M.MON_SLOTS * M.MON_STRIDE,
  battle_trainer_mons = M.MON_SLOTS * M.MON_STRIDE,
}
M.KEYS = {} -- sorted key names
for k in pairs(M.LENGTHS) do M.KEYS[#M.KEYS + 1] = k end
table.sort(M.KEYS)

-- State per address: "M" measured (first-hand or by tools on that exact version), "D" derived
-- (v1.4 community value - 0x3FF0), "C" community value for that version, "U" unverified (single
-- source, other version or arithmetic), see the docs.
M.REVISIONS = {
  {
    name = "v1.0",
    addr = {
      party = 0x08CF727C, box = 0x08C9A144,
      mystatus = 0x08C7D350, misc = 0x08C6DDC8, bag = 0x08C6AC80, play_time = 0x08CF7D98,
      map_id = 0x08C6A894, player_x = 0x08C6A8A4, player_y = 0x08C6A8AC, event_flags = 0x08C7DDDC,
      battle_wild_foes = 0x08805638, battle_trainer_foes = 0x08804AF4,
      battle_wild_mons = 0x082041F4, battle_trainer_mons = 0x08205D04,
    },
    state = {
      party = "M", box = "M", misc = "M", bag = "M", mystatus = "D", play_time = "D", map_id = "D", player_x = "D",
      player_y = "D", event_flags = "D", battle_wild_foes = "U", battle_trainer_foes = "U",
      battle_wild_mons = "U", battle_trainer_mons = "U",
    },
  },
  {
    name = "v1.4",
    addr = {
      party = 0x08CFB26C, box = 0x08C9E134,
      mystatus = 0x08C81340, misc = 0x08C71DB8, bag = 0x08C6EC70, play_time = 0x08CFBD88,
      map_id = 0x08C6E884, player_x = 0x08C6E894, player_y = 0x08C6E89C, event_flags = 0x08C81DCC,
      battle_flag = 0x081FB478, battle_wild_foes = 0x081FFA6C,
    },
    state = {
      party = "C", box = "C", misc = "C", bag = "D", mystatus = "C", play_time = "C", map_id = "C", player_x = "C",
      player_y = "C", event_flags = "C", battle_flag = "C", battle_wild_foes = "C",
    },
  },
}

-- "0x08C12345" or "08C12345" -> integer; nil when not a nonzero 32 bit hex number.
function M.parse_addr(s)
  if type(s) ~= "string" then return nil end
  local h = s:match("^%s*0[xX](%x+)%s*$") or s:match("^%s*(%x+)%s*$")
  if not h or #h > 8 then return nil end
  local n = tonumber(h, 16)
  if not n or n == 0 then return nil end
  return n
end

local function known_revision(name)
  for _, r in ipairs(M.REVISIONS) do if r.name == name then return true end end
  return false
end

-- Parses the text of config/addresses.txt. Lines: `key=0xADDR` (all revisions) or
-- `v1.0.key=0xADDR` (one revision); `#` starts a comment. Returns
-- { generic = {key=addr}, rev = {["v1.0"] = {key=addr}}, bad = { "line text", ... } }.
function M.parse_overrides(text)
  local out = { generic = {}, rev = {}, bad = {} }
  if type(text) ~= "string" then return out end
  for line in (text .. "\n"):gmatch("([^\r\n]*)\r?\n") do
    local l = line:gsub("#.*$", ""):match("^%s*(.-)%s*$")
    if l ~= "" then
      local key, val = l:match("^([%w_%.]+)%s*=%s*(.-)$")
      local addr = M.parse_addr(val)
      local rev, k = nil, key
      if key then
        local r, rest = key:match("^(v%d+%.%d+)%.([%w_]+)$")
        if r then rev, k = r, rest end
      end
      if addr and k and M.LENGTHS[k] and (rev == nil or known_revision(rev)) then
        if rev then
          out.rev[rev] = out.rev[rev] or {}
          out.rev[rev][k] = addr
        else
          out.generic[k] = addr
        end
      else
        out.bad[#out.bad + 1] = l
      end
    end
  end
  return out
end

-- Reads both override files from the plugin cache. config/zone_addr.txt sets map_id for all revisions.
function M.load_overrides(uz)
  local function read(name)
    if uz.cache and uz.cache.read then
      local ok, v = pcall(uz.cache.read, name)
      if ok and type(v) == "string" then return v end
    end
  end
  local ov = M.parse_overrides(read(M.OVERRIDE_FILE))
  local z = M.parse_addr(read(M.ZONE_OVERRIDE_FILE))
  if z then ov.generic.map_id = z end
  return ov
end

-- Effective addresses for one revision: revision override > generic override > table.
function M.resolve(rev, overrides)
  local out = {}
  for k in pairs(M.LENGTHS) do out[k] = rev.addr[k] end
  if overrides then
    for k, a in pairs(overrides.generic or {}) do out[k] = a end
    for k, a in pairs((overrides.rev or {})[rev.name] or {}) do out[k] = a end
  end
  return out
end

return M

end
__mod["gen6.oras_battle"] = function(...)
-- Battle state and wild encounters of Omega Ruby / Alpha Sapphire, derived from emulator memory.
-- The opponent party buffers and the battle-mon arrays PERSIST after a battle, so "in battle" is
-- inferred (docs/games/omega-ruby-alpha-sapphire.md, section Battle):
--   start : the content of an opponent buffer (slot 1) changed to valid, checksummed PK6 data AND
--           the battle-mon array holds a plausible entry matching it (AND, where an address is
--           known, the in-battle flag reads 0x00040001);
--   end   : the in-battle flag drops, or the map/zone changes, or the overworld position changes,
--           or the battle-mon array no longer matches the foes (3 polls in a row).
-- Wild vs trainer = which buffer changed. Horde = foe slots 2..5 all valid (and matched).
local addr = require("gen6.oras_addr")

local M = {}

M.PENDING_POLLS = 150  -- polls to wait for the battle-mon array after the buffer changed
M.END_MISS = 3         -- polls without a matching battle-mon before the battle counts as over
M.POS_EPSILON = 0.01   -- overworld position change that ends a battle
M.MAX_ENCOUNTERS = 64
M.WILD_SLOTS, M.TRAINER_SLOTS = 5, 6
M.MON_SPECIES, M.MON_MAX_HP, M.MON_HP, M.MON_LEVEL = 0x0C, 0x0E, 0x10, 0x18
M.MAX_SPECIES = 721
local RAW_LEN = 0xE8

-- env: addr(key) -> address|nil, read_slot(address) -> record|nil (checksummed, live stats merged),
--      position() -> zone, x, y, team() -> list|nil, location_id(zone) -> id|nil
function M.new(uz, env)
  local self = {}
  local st = { active = false }
  local last_raw = {}
  local pending = {}
  local encounters, seq = {}, 0
  local polls = 0

  local function kind_addr(kind, what) return env.addr("battle_" .. kind .. "_" .. what) end

  -- Plausible battle-mon entries { species, max_hp, hp, level, index }; nil when no array address,
  -- {} when the array is unreadable.
  local function read_mons(kind)
    local a = kind_addr(kind, "mons")
    if not a then return nil end
    local raw = uz.memory.bytes(a, addr.MON_SLOTS * addr.MON_STRIDE)
    local out = {}
    if not raw then return out end
    for i = 0, addr.MON_SLOTS - 1 do
      local o = i * addr.MON_STRIDE
      local species = string.unpack("<I2", raw, o + M.MON_SPECIES + 1)
      local max_hp = string.unpack("<I2", raw, o + M.MON_MAX_HP + 1)
      local hp = string.unpack("<I2", raw, o + M.MON_HP + 1)
      local level = raw:byte(o + M.MON_LEVEL + 1)
      if species >= 1 and species <= M.MAX_SPECIES and max_hp >= 1 and hp <= max_hp and level >= 1 and level <= 100 then
        out[#out + 1] = { species = species, max_hp = max_hp, hp = hp, level = level, index = i }
      end
    end
    return out
  end

  -- Valid PK6 records of an opponent buffer in slot order.
  local function candidates(kind)
    local a = kind_addr(kind, "foes")
    if not a then return {} end
    local n = kind == "wild" and M.WILD_SLOTS or M.TRAINER_SLOTS
    local out = {}
    for i = 1, n do
      local rec = env.read_slot(a + (i - 1) * addr.PARTY_STRIDE)
      if rec then rec.slot = i; out[#out + 1] = rec end
    end
    return out
  end

  local function matches(rec, mon)
    return mon.species == rec.species and (rec.level == nil or mon.level == rec.level)
  end

  local function foe_record(rec, mon)
    return {
      species = rec.species, form = rec.form, level = mon and mon.level or rec.level,
      hp = mon and mon.hp or rec.hp, max_hp = mon and mon.max_hp or rec.max_hp,
      shiny = rec.shiny, personality = rec.personality,
    }
  end

  -- Foes and horde flag of the battle of `kind` from the current memory.
  local function compute_foes(kind)
    local cands = candidates(kind)
    local mons = read_mons(kind)
    local foes, used, horde_slots = {}, {}, 0
    for _, rec in ipairs(cands) do
      local mon
      if mons then
        for j = #mons, 1, -1 do
          if not used[j] and matches(rec, mons[j]) then used[j] = true; mon = mons[j]; break end
        end
      end
      local active = mons == nil and rec.slot == 1 or mon ~= nil
      if active then
        foes[#foes + 1] = foe_record(rec, mon)
        if rec.slot >= 2 then horde_slots = horde_slots + 1 end
      end
    end
    local horde = kind == "wild" and horde_slots >= 4
    if mons == nil and kind == "wild" then -- no array: horde = slots 2..5 valid
      local n = 0
      for _, rec in ipairs(cands) do if rec.slot >= 2 then n = n + 1 end end
      horde = n >= 4
      foes = {}
      for _, rec in ipairs(cands) do
        if rec.slot == 1 or horde then foes[#foes + 1] = foe_record(rec, nil) end
      end
    end
    return foes, horde, mons, used
  end

  local function flag_ok()
    local a = env.addr("battle_flag")
    if not a then return true end
    return uz.memory.u32(a) == addr.FLAG_BATTLE
  end

  local function confirmed(kind)
    local cands = candidates(kind)
    local first = cands[1]
    if not first or first.slot ~= 1 then return false end
    local mons = read_mons(kind)
    if mons ~= nil then
      local hit = false
      for _, m in ipairs(mons) do if matches(first, m) then hit = true; break end end
      if not hit then return false end
    end
    return flag_ok()
  end

  local function species_list(foes)
    local out = {}
    for i, f in ipairs(foes) do out[i] = f.species end
    return out
  end

  local function start(kind)
    local foes, horde = compute_foes(kind)
    if #foes == 0 then return false end
    local zone, x, y = env.position()
    st = { active = true, kind = kind, horde = horde, zone = zone, x = x, y = y, miss = 0 }
    uz.events.emit("battle.started", { kind = kind, horde = horde, foes = species_list(foes) })
    if kind == "wild" then
      seq = seq + 1
      local first = foes[1]
      local entry = {
        seq = seq, species = first.species, form = first.form, level = first.level, shiny = first.shiny,
        horde = horde, zone = zone, location = zone and env.location_id(zone) or nil,
        frame = uz.memory.frame and uz.memory.frame() or polls,
      }
      entry.species_name = env.species_name and env.species_name(first.species) or nil
      encounters[#encounters + 1] = entry
      if #encounters > M.MAX_ENCOUNTERS then table.remove(encounters, 1) end
      uz.events.emit("encounter", entry)
    end
    return true
  end

  local function finish()
    local kind = st.kind
    st = { active = false }
    pending = {}
    uz.events.emit("battle.ended", { kind = kind })
  end

  local function over()
    local a = env.addr("battle_flag")
    if a then
      local v = uz.memory.u32(a)
      if v ~= nil and v ~= addr.FLAG_BATTLE then return true end
    end
    local zone, x, y = env.position()
    if zone and st.zone and zone ~= st.zone then return true end
    if x and y and st.x and st.y
      and (math.abs(x - st.x) > M.POS_EPSILON or math.abs(y - st.y) > M.POS_EPSILON) then
      return true
    end
    local foes, _, mons = compute_foes(st.kind)
    if mons ~= nil and #foes == 0 then
      st.miss = st.miss + 1
      return st.miss >= M.END_MISS
    end
    st.miss = 0
    return false
  end

  -- Called every tick. Never raises (the caller wraps it in pcall).
  function self.poll()
    polls = polls + 1
    local any = false
    for _, kind in ipairs({ "wild", "trainer" }) do
      local a = kind_addr(kind, "foes")
      if a then
        any = true
        local raw = uz.memory.bytes(a, RAW_LEN)
        if raw then
          if last_raw[kind] == nil then
            last_raw[kind] = raw -- baseline, no event
          elseif raw ~= last_raw[kind] then
            last_raw[kind] = raw
            if not st.active then
              local rec = env.read_slot(a)
              if rec then pending[kind] = 0 end
            end
          end
        end
      end
    end
    if not any then return end
    if st.active then
      if over() then finish() end
      return
    end
    for _, kind in ipairs({ "wild", "trainer" }) do
      if pending[kind] then
        pending[kind] = pending[kind] + 1
        if confirmed(kind) then
          pending = {}
          if start(kind) then return end
        elseif pending[kind] > M.PENDING_POLLS then
          pending[kind] = nil
        end
      end
    end
  end

  function self.available()
    return env.addr("battle_wild_foes") ~= nil or env.addr("battle_trainer_foes") ~= nil
  end

  -- { active, kind, horde, foes, own }
  function self.battle()
    if not st.active then return { active = false } end
    local foes, horde, mons, used = compute_foes(st.kind)
    local own = {}
    if mons then
      local team = env.team() or {}
      local taken = {}
      for j, m in ipairs(mons) do
        if not used[j] then
          for pi, p in ipairs(team) do
            if not taken[pi] and p.species == m.species and (p.level == nil or p.level == m.level) then
              taken[pi] = true
              own[#own + 1] = { personality = p.personality, species = m.species, hp = m.hp, max_hp = m.max_hp, slot = p.slot }
              break
            end
          end
        end
      end
    end
    return { active = true, kind = st.kind, horde = st.horde or horde, foes = foes, own = own }
  end

  function self.encounters()
    local out = {}
    for i, e in ipairs(encounters) do out[i] = e end
    return out
  end

  return self
end

return M

end
__mod["gen6.pal_bclim"] = function(...)
-- Gen 6 palette BCLIM decoder in Lua (box icons). The Player's uz.codec.bclim decodes this variant
-- too, but with one fixed set of choices (RGBA5551 colours, low nibble first) that did not give a
-- usable picture on a real Omega Ruby (v0.3.3 field report). The choices are parameters here so
-- variants can be compared (icon_variants); the field report on a real Omega Ruby EU confirmed
-- variant D, which is the default (DEFAULT_VARIANT).
--
-- Layout (pk3DS pk3DS.Core/CTR/Images/BCLIM.cs, GetPixelsViaPalette; Player texture.cpp), pixel data
-- of a BCLIM whose footer format is 7 and whose data starts with u16 2:
--   u16 2, u16 colour count, count x u16 colours, then the indices in 8x8 Morton tiles, tile rows
--   BaseSize/8 tiles wide (BaseSize = next power of two of max(w, h), 64 for 40x30). Indices are
--   4 bit (two per byte) when the count is at most 16, else 8 bit.
-- pk3DS reads the colours as RGB565 with low nibble first; its writer (BCLIM.cs) writes RGBA5551,
-- forces transparent pixels to index 0 and puts the FIRST pixel in the HIGH nibble. The game files
-- follow the writer (RGBA5551, index 0 not forced transparent, high nibble first: variant D); the
-- other variants stay for diagnostics. Nothing is shipped.
local M = {}

M.FOOTER = 0x28
M.FMT_OFFSET = 0x20          -- format byte inside the footer
M.MAX_DIM = 1024

-- Variant table. color: "565" | "5551"; index0: index 0 is transparent (565 has no alpha bit);
-- high_first: the first (even) pixel of a byte sits in the high nibble.
M.VARIANTS = {
  A = { color = "565", index0 = true, high_first = false, desc = "RGB565, index 0 transparent, low nibble first" },
  B = { color = "5551", index0 = false, high_first = false, desc = "RGBA5551, low nibble first" },
  C = { color = "565", index0 = true, high_first = true, desc = "RGB565, index 0 transparent, high nibble first" },
  D = { color = "5551", index0 = false, high_first = true, desc = "RGBA5551, high nibble first" },
}
-- E: no palette at all; the data is a plain tiled 16-bit texture (RGBA5551, the footer format 7).
-- The Player treats every format 7 image whose first u16 is 2 as a palette image, which also
-- catches a plain texture whose first pixel happens to be 0x0002 (transparent). Plain texture data
-- is exactly pow2(w) x pow2(h) x 2 bytes (64 x 32 x 2 = 4096 for a 40x30 icon).
M.VARIANTS.E = { plain = true, color = "5551", desc = "plain tiled RGBA5551, no palette" }
M.ORDER = { "A", "B", "C", "D", "E" }
-- The variant icon() uses: D, confirmed on a real Omega Ruby EU (clean, correctly coloured icons).
M.DEFAULT_VARIANT = "D"

local function pow2_at_least_8(v)
  local p = 8
  while p < v do p = p << 1 end
  return p
end

-- width, height, format byte of the BCLIM footer, or nil.
local function footer(s)
  if type(s) ~= "string" or #s < M.FOOTER then return nil end
  local f = #s - M.FOOTER + 1
  if s:sub(f, f + 3) ~= "CLIM" or s:sub(f + 0x14, f + 0x17) ~= "imag" then return nil end
  local w, h = string.unpack("<I2I2", s, f + 0x1C)
  return w, h, s:byte(f + M.FMT_OFFSET)
end

-- True for a format 7 BCLIM whose data starts with u16 2 and a nonzero colour count.
function M.is_palette(s)
  local w, h, fmt = footer(s)
  if not w or fmt ~= 7 or #s < M.FOOTER + 4 then return false end
  local a, count = string.unpack("<I2I2", s, 1)
  return a == 2 and count >= 1
end

-- True when the data (without footer) is a palette image whose index bytes needed for the image
-- fit behind the palette and everything after them up to the end of the data is zero padding.
-- Needed indices: all tiles up to the last tile row of the image (stride = BaseSize as in decode).
local function padded_palette(s)
  if not M.is_palette(s) then return false end
  local w, h = footer(s)
  local size = #s - M.FOOTER
  local count = string.unpack("<I2", s, 3)
  if count > 256 then return false end
  local stride = pow2_at_least_8(math.max(w, h))
  local pixels = ((h + 7) // 8) * (stride // 8) * 64
  local nbytes = (count <= 16) and ((pixels + 1) // 2) or pixels
  local last = 4 + 2 * count + nbytes
  if last > size then return false end
  for i = last + 1, size do
    if s:byte(i) ~= 0 then return false end
  end
  return true
end

-- "plain16" when the data size is exactly that of a plain tiled 16-bit texture of the footer size
-- (format 7 RGBA5551 or 5 RGB565), unless the palette signature holds and the data is a palette
-- image zero-padded to that size (real Omega Ruby icons: 40x30, 12 colours, 4096 data bytes), then
-- "palette". Without the plain size, the palette signature means "palette", else nil.
function M.layout(s)
  local w, h, fmt = footer(s)
  if not w or w < 1 or h < 1 or w > M.MAX_DIM or h > M.MAX_DIM then return nil end
  if fmt == 7 or fmt == 5 then
    if #s - M.FOOTER == pow2_at_least_8(w) * pow2_at_least_8(h) * 2 then
      if padded_palette(s) then return "palette" end
      return "plain16"
    end
  end
  if M.is_palette(s) then return "palette" end
  return nil
end

-- Plain facts for diagnostics: { count, pal = { u16... (first 8) }, idx = { bytes... (first 8) },
-- idx_bytes = bytes left for the indices } or nil when the data is no palette BCLIM.
function M.inspect(s)
  if not M.is_palette(s) then return nil end
  local size = #s - M.FOOTER
  local count = string.unpack("<I2", s, 3)
  local out = { count = count, pal = {}, idx = {}, idx_bytes = size - 4 - 2 * count }
  for i = 1, math.min(8, count) do
    local o = 4 + (i - 1) * 2 + 1
    if o + 1 <= size then out.pal[#out.pal + 1] = string.unpack("<I2", s, o) end
  end
  local base = 4 + 2 * count
  for i = 1, 8 do
    if base + i <= size then out.idx[#out.idx + 1] = s:byte(base + i) end
  end
  return out
end

local function expand(v, bits)
  if bits == 5 then return (v << 3) | (v >> 2) end
  return (v << 2) | (v >> 4)
end

-- Colour u16 -> r, g, b, a (0..255).
function M.color(v, mode)
  if mode == "565" then
    return expand((v >> 11) & 31, 5), expand((v >> 5) & 63, 6), expand(v & 31, 5), 255
  end
  return expand((v >> 11) & 31, 5), expand((v >> 6) & 31, 5), expand((v >> 1) & 31, 5), (v & 1) == 1 and 255 or 0
end

-- Morton position inside an 8x8 tile: MORTON[(y % 8) * 8 + x % 8] = index 0..63
local MORTON = {}
for y = 0, 7 do
  for x = 0, 7 do
    MORTON[y * 8 + x] = (x & 1) | ((y & 1) << 1) | ((x & 2) << 1) | ((y & 2) << 2) | ((x & 4) << 2) | ((y & 4) << 3)
  end
end

-- Decodes a palette BCLIM. opts: color "565"|"5551" (default "565"), index0 (index 0 transparent,
-- default true), high_first (default false), bits 4|8 (default: 4 when the count is at most 16),
-- stride (tile layout width in pixels, multiple of 8; default BaseSize = next power of two of
-- max(w, h)). Returns { width, height, rgba } or nil, reason.
function M.decode(s, opts)
  opts = opts or {}
  if not M.is_palette(s) then return nil, "not_palette" end
  local w, h = footer(s)
  if w < 1 or h < 1 or w > M.MAX_DIM or h > M.MAX_DIM then return nil, "size" end
  local mode = opts.color or "565"
  local index0 = opts.index0
  if index0 == nil then index0 = true end
  local size = #s - M.FOOTER
  local count = string.unpack("<I2", s, 3)
  if 4 + 2 * count > size then return nil, "palette_truncated" end
  local bits = opts.bits or (count <= 16 and 4 or 8)
  local stride = opts.stride or pow2_at_least_8(math.max(w, h))
  if stride % 8 ~= 0 or stride < w then return nil, "stride" end
  local tiles_x = stride // 8
  local base = 4 + 2 * count -- 0-based offset of the indices
  local pal = {}
  for c = 0, count - 1 do
    local r, g, b, a = M.color(string.unpack("<I2", s, 5 + c * 2), mode)
    if index0 and c == 0 then a = 0 end
    if index0 and c ~= 0 and mode == "565" then a = 255 end
    pal[c] = string.char(r, g, b, a)
  end
  local clear = "\0\0\0\0"
  local rows = {}
  for y = 0, h - 1 do
    local row = {}
    for x = 0, w - 1 do
      local n = ((y >> 3) * tiles_x + (x >> 3)) * 64 + MORTON[(y & 7) * 8 + (x & 7)]
      local idx
      if bits == 4 then
        local o = base + (n >> 1) + 1
        if o > size then return nil, "indices_truncated" end
        local b = s:byte(o)
        local first = (n & 1) == 0
        if opts.high_first then idx = first and (b >> 4) or (b & 15) else idx = first and (b & 15) or (b >> 4) end
      else
        local o = base + n + 1
        if o > size then return nil, "indices_truncated" end
        idx = s:byte(o)
      end
      row[x + 1] = pal[idx] or clear
    end
    rows[y + 1] = table.concat(row)
  end
  return { width = w, height = h, rgba = table.concat(rows) }
end

-- Decodes a plain tiled 16-bit texture ("plain16" layout), cropped to the footer size.
-- opts.color: "5551" (default for format 7) or "565" (default for format 5).
function M.decode_plain(s, opts)
  opts = opts or {}
  local w, h, fmt = footer(s)
  if M.layout(s) ~= "plain16" then return nil, "not_plain16" end
  local mode = opts.color or (fmt == 5 and "565" or "5551")
  local tiles_x = pow2_at_least_8(w) // 8
  local rows = {}
  for y = 0, h - 1 do
    local row = {}
    for x = 0, w - 1 do
      local n = ((y >> 3) * tiles_x + (x >> 3)) * 64 + MORTON[(y & 7) * 8 + (x & 7)]
      local r, g, b, a = M.color(string.unpack("<I2", s, n * 2 + 1), mode)
      row[x + 1] = string.char(r, g, b, a)
    end
    rows[y + 1] = table.concat(row)
  end
  return { width = w, height = h, rgba = table.concat(rows) }
end

-- Decodes `s` as named variant A..E, or nil, reason.
function M.decode_variant(s, label)
  local v = M.VARIANTS[label]
  if not v then return nil, "unknown_variant" end
  if v.plain then return M.decode_plain(s, { color = v.color }) end
  return M.decode(s, M.variant_opts(label))
end

-- Decodes an icon the way icon() does: plain 16-bit layout as a plain texture, palette layout with
-- the default variant; nil when the data is neither (the caller uses uz.codec.bclim).
function M.decode_auto(s)
  local layout = M.layout(s)
  if layout == "plain16" then return M.decode_plain(s) end
  if layout == "palette" then return M.decode(s, M.variant_opts(M.DEFAULT_VARIANT)) end
  return nil, "not_palette"
end

-- Options of a named variant (A..D), or nil.
function M.variant_opts(label)
  local v = M.VARIANTS[label]
  if not v then return nil end
  return { color = v.color, index0 = v.index0, high_first = v.high_first }
end

return M

end
__mod["gen6.personal"] = function(...)
-- Growth rate per species, read at runtime from the user's own game files
-- (RomFS personal GARC). Nothing from the game is shipped or persisted; the
-- values live in a Lua table cache only.
--
-- ORAS personal data (community-documented, all to verify locally):
--   path  : candidates "/a/1/9/5" and "/a/1/9/6", tried in order; the first one
--           whose data validates as a personal table is used (see validate)
--   entry : 0x50 bytes per species (PKHeX PersonalInfoORAS), index = Dex number
--   growth: byte 0x15 of the entry (PersonalInfoORAS.EXPGrowth), values 0..5
--   types : bytes 0x06 / 0x07 (Type1 / Type2, same value = single type)
-- /a/1/9/5 is the confirmed ORAS path (pk3DS GARCReference); the LAST GARC file holds the whole
-- table concatenated (pk3DS GameConfig). Accepted shapes: the last file (or the only one) with
-- length % 0x50 == 0 and >= 722 entries, or >= 722 files of 0x50 bytes (file species + 1 is the
-- entry of that species).
local garc_entry = require("gen6.garc_entry")
local M = {}

M.CANDIDATE_PATHS = { "/a/1/9/5", "/a/1/9/6" }
M.TYPE_OFFSET = 0x06 -- Type1, Type2 follows
M.ENTRY_SIZE = 0x50
M.GROWTH_OFFSET = 0x15
M.BASE_STATS_OFFSET = 0x00 -- 6 bytes HP, Atk, Def, Spe, SpA, SpD (PKHeX PersonalInfo, recalled, not verified on a device)
M.ABILITY_OFFSET = 0x18 -- Ability 1, Ability 2, Hidden Ability (u8 each; PKHeX PersonalInfoORAS, recalled, not verified on a device)
M.FORM_INDEX_OFFSET = 0x1C -- u16 FormStatsIndex (PKHeX PersonalInfoXY/ORAS), 0 = no extra forms
M.FORM_COUNT_OFFSET = 0x20 -- u8 FormeCount
M.MIN_ENTRIES = 722 -- species 0..721
M.MAX_ATTEMPTS = 3

function M.new(uz, opts)
  opts = opts or {}
  local paths = opts.paths or M.CANDIDATE_PATHS
  local esize = opts.entry_size or M.ENTRY_SIZE
  local goff = opts.growth_offset or M.GROWTH_OFFSET
  local self = {}
  local rates, forms, attempts = nil, nil, 0
  local whole_data, garc_data -- entry source: concatenated table, or the GARC itself
  local first_reject = nil
  local function reject(why) if not first_reject then first_reject = why end end

  local function form_info(e, out_forms, s)
    local idx = string.unpack("<I2", e, M.FORM_INDEX_OFFSET + 1)
    local cnt = e:byte(M.FORM_COUNT_OFFSET + 1)
    out_forms[s] = { index = idx, count = cnt }
  end

  -- Returns a table species -> rate (1..721), a table species -> {index, count} and the source of
  -- the entries ("whole", string | "files"), or nil when data is not a personal table.
  local function validate(data)
    local g, gerr = uz.codec.garc(data)
    if type(g) ~= "table" or type(g.count) ~= "number" then
      reject("garc_rejected: " .. (tostring(gerr):gsub("[^%w _%.:%-]", "?"):sub(1, 40)))
      return nil
    end
    local out, fo = {}, {}
    local whole
    local last = garc_entry.entry(uz.codec, data, g.count)
    if type(last) == "string" and #last % esize == 0 and #last // esize >= M.MIN_ENTRIES then whole = last end
    if whole then
      for s = 1, M.MIN_ENTRIES - 1 do
        local r = whole:byte(s * esize + goff + 1)
        if not r or r > 5 then reject("growth_invalid"); return nil end
        out[s] = r
        form_info(whole:sub(s * esize + 1, s * esize + esize), fo, s)
      end
      return out, fo, whole
    elseif g.count >= M.MIN_ENTRIES then
      for s = 1, M.MIN_ENTRIES - 1 do
        local e = garc_entry.entry(uz.codec, data, s + 1)
        if type(e) ~= "string" or #e ~= esize then reject("entry_size"); return nil end
        local r = e:byte(goff + 1)
        if r > 5 then return nil end
        out[s] = r
        form_info(e, fo, s)
      end
      return out, fo, nil
    end
    reject("table_shape")
    return nil
  end

  local function load()
    if rates then return true end
    if attempts >= M.MAX_ATTEMPTS then return false end
    attempts = attempts + 1
    if not (uz and uz.rom and uz.rom.romfs and uz.codec and uz.codec.garc and uz.codec.garc_file) then
      return false
    end
    for _, path in ipairs(paths) do
      local data = uz.rom.romfs(path)
      if type(data) ~= "string" then reject("romfs_unreadable") end
      if type(data) == "string" then
        local r, fo, whole = validate(data)
        if r then
          rates, forms, whole_data, garc_data = r, fo, whole, data
          self.path = path
          if uz.log and uz.log.info then uz.log.info("personal data accepted at " .. path) end
          return true
        end
      end
    end
    return false
  end

  -- Growth rate 0..5 for a species (Dex number 1..721), or nil.
  function self.growth_rate(species)
    if math.type(species) ~= "integer" or species < 1 then return nil end
    if not load() then return nil end
    return rates[species]
  end

  -- Personal-table index of a species form (assumption, see docs): form 0 is the
  -- species itself; form f > 0 is FormStatsIndex + f - 1 when 0 < f < FormeCount.
  -- Returns the index, or nil, "not_ready" (table not readable) / "no_form".
  function self.form_index(species, form)
    if math.type(species) ~= "integer" or species < 1 or species >= M.MIN_ENTRIES then
      return nil, "no_form"
    end
    form = form or 0
    if form == 0 then return species end
    if not load() then return nil, "not_ready" end
    local f = forms[species]
    if not f or f.index == 0 or form < 0 or form >= f.count then return nil, "no_form" end
    return f.index + form - 1
  end

  -- Raw personal entry of a table index, or nil.
  local function raw_entry(idx)
    if whole_data then
      local e = whole_data:sub(idx * esize + 1, idx * esize + esize)
      return #e == esize and e or nil
    end
    local e = garc_entry.entry(uz.codec, garc_data, idx + 1)
    return (type(e) == "string" and #e == esize) and e or nil
  end

  -- { types = { t1, t2 }, growth } of a species form, or nil, "not_ready" | "unknown_species" | "no_form".
  function self.info(species, form)
    if math.type(species) ~= "integer" or species < 1 or species >= M.MIN_ENTRIES then
      return nil, "unknown_species"
    end
    local idx, err = self.form_index(species, form)
    if not idx then return nil, err end
    local e = raw_entry(idx)
    if not e then return nil, "no_form" end
    return { types = { e:byte(M.TYPE_OFFSET + 1), e:byte(M.TYPE_OFFSET + 2) }, growth = e:byte(goff + 1) }
  end

  -- { hp, atk, def, spe, spa, spd } base stats of a species form, or nil, "not_ready" | "unknown_species" | "no_form".
  function self.base_stats(species, form)
    if math.type(species) ~= "integer" or species < 1 or species >= M.MIN_ENTRIES then
      return nil, "unknown_species"
    end
    local idx, err = self.form_index(species, form)
    if not idx then return nil, err end
    local e = raw_entry(idx)
    if not e then return nil, "no_form" end
    local base = {}
    for i, k in ipairs({ "hp", "atk", "def", "spe", "spa", "spd" }) do base[k] = e:byte(M.BASE_STATS_OFFSET + i) end
    return base
  end

  -- { id1, id2, hidden } ability ids of a species form (0 = none), or nil, "not_ready" | "unknown_species" | "no_form".
  function self.abilities(species, form)
    if math.type(species) ~= "integer" or species < 1 or species >= M.MIN_ENTRIES then
      return nil, "unknown_species"
    end
    local idx, err = self.form_index(species, form)
    if not idx then return nil, err end
    local e = raw_entry(idx)
    if not e then return nil, "no_form" end
    return { e:byte(M.ABILITY_OFFSET + 1), e:byte(M.ABILITY_OFFSET + 2), e:byte(M.ABILITY_OFFSET + 3) }
  end

  -- Plain strings and numbers only.
  function self.diagnostics()
    return { personal_ok = rates and 1 or 0, personal_attempts = attempts, personal_first_rejection = first_reject or "none" }
  end

  -- Forget failures and cached values (e.g. after a game change).
  function self.reset()
    rates, forms, whole_data, garc_data, attempts, self.path = nil, nil, nil, nil, 0, nil
  end

  return self
end

return M

end
__mod["gen6.pk6"] = function(...)
-- Gen 6 PK6 parser for decrypted data (232 stored / 260 party bytes).
-- Layout: PKHeX PK6.cs (kwsch/PKHeX, PKHeX.Core/PKM/PK6.cs), offsets below are
-- from that file; cross-check: Project Pokemon "Pokemon X/Y save structure".
-- Strings are UTF-16LE, 12 characters + terminator (0x1A bytes).
local M = {}

M.SIZE_STORED = 232
M.SIZE_PARTY = 260
M.MAX_SPECIES = 721 -- ORAS National Dex

local OFF = {
  ec = 0x00, checksum = 0x06, species = 0x08, held_item = 0x0A, tid = 0x0C, sid = 0x0E,
  exp = 0x10, ability = 0x14, ability_num = 0x15, pid = 0x18, nature = 0x1C, flags = 0x1D, evs = 0x1E,
  nickname = 0x40, moves = 0x5A, iv32 = 0x74, ot_name = 0xB0, version = 0xDF, language = 0xE3,
  -- party extension (not trusted for live party memory, see parse)
  status = 0xE8, level = 0xEC, hp = 0xF0, max_hp = 0xF2, stats = 0xF4,
}
M.OFF = OFF

-- Language byte (PKHeX LanguageID; 6 is unused, 7 = Spanish) -> language code
local LANG = { [1] = "ja", [2] = "en", [3] = "fr", [4] = "it", [5] = "de", [7] = "es",
  [8] = "ko", [9] = "zh-Hans", [10] = "zh-Hant" }
M.LANGUAGES = LANG

local GENDER = { [0] = "male", [1] = "female", [2] = "genderless" }

-- UTF-16LE (up to max_chars code units, stops at 0x0000) -> UTF-8
function M.utf16le_to_utf8(s, max_chars)
  local out, i, n = {}, 1, 0
  max_chars = max_chars or (#s // 2)
  while n < max_chars and i + 1 <= #s do
    local u = string.unpack("<I2", s, i)
    i = i + 2
    n = n + 1
    if u == 0 then break end
    if u >= 0xD800 and u <= 0xDBFF and n < max_chars and i + 1 <= #s then
      local lo = string.unpack("<I2", s, i)
      if lo >= 0xDC00 and lo <= 0xDFFF then
        i = i + 2
        n = n + 1
        out[#out + 1] = utf8.char(0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00))
      else
        out[#out + 1] = utf8.char(0xFFFD)
      end
    elseif u >= 0xD800 and u <= 0xDFFF then
      out[#out + 1] = utf8.char(0xFFFD)
    else
      out[#out + 1] = utf8.char(u)
    end
  end
  return table.concat(out)
end

-- plain: decrypted PK6 (232 or 260 bytes). Returns record or nil, reason.
-- Level/HP/status of the live party are NOT filled from 0xE8+ (unreliable in
-- running ORAS memory); they are exposed as record.party_ext only.
function M.parse(plain)
  if type(plain) ~= "string" then return nil, "bad_type" end
  if #plain ~= M.SIZE_STORED and #plain ~= M.SIZE_PARTY then return nil, "bad_length" end
  local function u8(o) return (string.unpack("<I1", plain, o + 1)) end
  local function u16(o) return (string.unpack("<I2", plain, o + 1)) end
  local function u32(o) return (string.unpack("<I4", plain, o + 1)) end

  local pid, tid, sid = u32(OFF.pid), u16(OFF.tid), u16(OFF.sid)
  local flags = u8(OFF.flags)
  local iv32 = u32(OFF.iv32)
  local moves = {}
  for i = 0, 3 do
    local m = u16(OFF.moves + i * 2)
    if m ~= 0 then moves[#moves + 1] = m end
  end
  local evs, ivs = {}, {}
  for i, k in ipairs({ "hp", "atk", "def", "spe", "spa", "spd" }) do
    evs[k] = u8(OFF.evs + i - 1)
    ivs[k] = (iv32 >> (5 * (i - 1))) & 0x1F
  end
  local lang_id = u8(OFF.language)

  local rec = {
    species = u16(OFF.species),
    form = flags >> 3,
    nickname = M.utf16le_to_utf8(plain:sub(OFF.nickname + 1, OFF.nickname + 0x1A), 12),
    nicknamed = (iv32 >> 31) & 1 == 1,
    exp = u32(OFF.exp),
    personality = pid,
    encryption_constant = u32(OFF.ec),
    shiny = ((tid ~ sid ~ (pid >> 16) ~ (pid & 0xFFFF)) < 16),
    gender = GENDER[(flags >> 1) & 3],
    fateful = flags & 1 == 1,
    nature = u8(OFF.nature),
    ability = u8(OFF.ability),
    ability_num = u8(OFF.ability_num), -- bit 0 = ability 1, bit 1 = ability 2, bit 2 = hidden (PKHeX AbilityNumber)
    held_item = u16(OFF.held_item),
    moves = moves,
    ot_name = M.utf16le_to_utf8(plain:sub(OFF.ot_name + 1, OFF.ot_name + 0x1A), 12),
    ot_id = tid,
    ot_sid = sid,
    language = LANG[lang_id],
    language_id = lang_id,
    origin_game = u8(OFF.version),
    egg = (iv32 >> 30) & 1 == 1,
    ivs = ivs,
    evs = evs,
    -- level, hp, max_hp, status: nil here; level comes from growth
  }
  if #plain == M.SIZE_PARTY then
    local stats = {}
    for i, k in ipairs({ "atk", "def", "spe", "spa", "spd" }) do
      stats[k] = u16(OFF.stats + (i - 1) * 2)
    end
    rec.party_ext = {
      status = u32(OFF.status), level = u8(OFF.level),
      hp = u16(OFF.hp), max_hp = u16(OFF.max_hp), stats = stats,
    }
  end
  return rec
end

-- Crypto (PKHeX PokeCrypto.cs, same algorithm as the host helpers uz.codec.pk6_decrypt / pk6_encrypt,
-- kept here so write helpers do not depend on the host). seed = encryption constant (first u32);
-- seed = seed * 0x41C64E6D + 0x6073 (32 bit); each u16 is xored with seed >> 16. Bytes 0x08..0xE7 are
-- crypted and their four 56-byte blocks shuffled by (EC >> 13) & 31 modulo 24; the party extension
-- 0xE8.. is crypted with a fresh stream seeded by the same constant.
local ORDER = {
  {0,1,2,3},{0,1,3,2},{0,2,1,3},{0,3,1,2},{0,2,3,1},{0,3,2,1},
  {1,0,2,3},{1,0,3,2},{2,0,1,3},{3,0,1,2},{2,0,3,1},{3,0,2,1},
  {1,2,0,3},{1,3,0,2},{2,1,0,3},{3,1,0,2},{2,3,0,1},{3,2,0,1},
  {1,2,3,0},{1,3,2,0},{2,1,3,0},{3,1,2,0},{2,3,1,0},{3,2,1,0},
}
local BLOCK = 56

-- u16 sum over 0x08..0xE7 of a decrypted structure.
function M.checksum(plain)
  local sum = 0
  for o = 0x08, 0xE6, 2 do sum = sum + string.unpack("<I2", plain, o + 1) end
  return sum & 0xFFFF
end

local function crypt(s, seed)
  local out = {}
  for i = 1, #s - 1, 2 do
    seed = (seed * 0x41C64E6D + 0x6073) & 0xFFFFFFFF
    out[#out + 1] = string.pack("<I2", string.unpack("<I2", s, i) ~ (seed >> 16))
  end
  if #s % 2 == 1 then out[#out + 1] = s:sub(-1) end
  return table.concat(out)
end

-- decrypted block i (0-based) = encrypted block ORDER[sv][i]
local function shuffle(body, sv, inverse)
  local order = ORDER[sv % 24 + 1]
  local out = {}
  for i = 1, 4 do
    local from = order[i]
    if inverse then
      out[from + 1] = body:sub((i - 1) * BLOCK + 1, i * BLOCK)
    else
      out[i] = body:sub(from * BLOCK + 1, (from + 1) * BLOCK)
    end
  end
  return table.concat(out)
end

local function good_len(s)
  return type(s) == "string" and (#s == M.SIZE_STORED or #s == M.SIZE_PARTY)
end

-- enc -> plain, checksum_ok; nil, "bad_length" for other input.
function M.decrypt(enc)
  if not good_len(enc) then return nil, "bad_length" end
  local ec = string.unpack("<I4", enc)
  local body = shuffle(crypt(enc:sub(9, 232), ec), (ec >> 13) & 31, false)
  local plain = enc:sub(1, 8) .. body
  if #enc == M.SIZE_PARTY then plain = plain .. crypt(enc:sub(233), ec) end
  return plain, string.unpack("<I2", plain, 7) == M.checksum(plain)
end

-- Encrypts without touching the checksum.
function M.encrypt(plain)
  if not good_len(plain) then return nil, "bad_length" end
  local ec = string.unpack("<I4", plain)
  local body = crypt(shuffle(plain:sub(9, 232), (ec >> 13) & 31, true), ec)
  local enc = plain:sub(1, 8) .. body
  if #plain == M.SIZE_PARTY then enc = enc .. crypt(plain:sub(233), ec) end
  return enc
end

-- plain with a recomputed checksum at 0x06.
function M.with_checksum(plain)
  if not good_len(plain) then return nil, "bad_length" end
  return plain:sub(1, 6) .. string.pack("<I2", M.checksum(plain)) .. plain:sub(9)
end

-- Recomputes the checksum, then encrypts.
function M.seal(plain)
  local p, err = M.with_checksum(plain)
  if not p then return nil, err end
  return M.encrypt(p)
end

-- UTF-8 -> UTF-16LE with exactly `chars` code units (cut or zero padded; no terminator is forced
-- when the text fills all units, as in the game's 12 character + terminator field when chars = 13).
function M.utf8_to_utf16le(s, chars)
  local out, n = {}, 0
  for _, c in utf8.codes(s) do
    if c >= 0x10000 then
      if n + 2 > chars then break end
      c = c - 0x10000
      out[#out + 1] = string.pack("<I2I2", 0xD800 + (c >> 10), 0xDC00 + (c & 0x3FF))
      n = n + 2
    else
      if n + 1 > chars then break end
      out[#out + 1] = string.pack("<I2", c)
      n = n + 1
    end
  end
  return table.concat(out) .. string.rep("\0", (chars - n) * 2)
end

